float _density = -1;
java.util.Map _dpCache = new java.util.HashMap();

int dp(int d) {
    Integer cached = (Integer) _dpCache.get(new Integer(d));
    if (cached != null) return cached.intValue();
    if (_density <= 0) {
        android.content.Context ctx = hostContext;
        if (ctx == null) _density = 3.0f;
        else _density = ctx.getResources().getDisplayMetrics().density;
    }
    int result = (int) (d * _density + 0.5f);
    _dpCache.put(new Integer(d), new Integer(result));
    return result;
}

java.util.Map _colorCache = new java.util.HashMap();

int c(String hex) {
    Integer cached = (Integer) _colorCache.get(hex);
    if (cached != null) return cached.intValue();
    int result = android.graphics.Color.parseColor("#" + hex);
    _colorCache.put(hex, new Integer(result));
    return result;
}

android.widget.TextView T(android.content.Context ctx, String text, int size, int color, boolean bold) {
    android.widget.TextView tv = new android.widget.TextView(ctx);
    tv.setText(text);
    tv.setTextSize(size);
    tv.setTextColor(color);
    if (bold) tv.setTypeface(android.graphics.Typeface.DEFAULT_BOLD);
    return tv;
}

android.view.View SP(android.content.Context ctx, int h) {
    android.view.View v = new android.view.View(ctx);
    v.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1, dp(h)));
    return v;
}

android.view.View H(int cl, int h) {
    if (hostContext == null) return new android.view.View(null);
    android.view.View v = new android.view.View(hostContext);
    v.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1, dp(h)));
    v.setBackgroundColor(cl);
    return v;
}

// ===== 异步任务线程池 =====
java.util.concurrent.ExecutorService _pool;
java.util.concurrent.ExecutorService getPool() {
    if (_pool == null || _pool.isShutdown()) {
        _pool = java.util.concurrent.Executors.newCachedThreadPool();
    }
    return _pool;
}
void exec(java.lang.Runnable r) { getPool().execute(r); }

