int[] candyColors() {
    boolean dark = isDarkMode();
    if (dark) {
        return new int[]{
            c("FF1E0430"), c("FF081838"), c("FF082438"),
            c("FF140E38"), c("FF200840"), c("FF1E0430")
        };
    }
    return new int[]{
        c("FFFFE8F4"), c("FFFCD4EE"), c("FFF0D4FF"),
        c("FFD4E6FF"), c("FFD8F4EE"), c("FFFFE4F4")
    };
}

GradientDrawable createGlassBg(int rad) {
    GradientDrawable gd = new GradientDrawable();
    gd.setOrientation(GradientDrawable.Orientation.TL_BR);
    gd.setColors(candyColors());
    gd.setCornerRadius(dp(rad));
    gd.setStroke(dp(1), c("FF" + thGlassBd()));
    return gd;
}

