// ===== XKR HTTP/JSON 辅助方法 =====
String jdyHttpGet(String urlStr) {
    try {
        java.net.URL u = new java.net.URL(urlStr);
        java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
        conn.setConnectTimeout(8000);
        conn.setReadTimeout(8000);
        conn.setRequestMethod("GET");
        int code = conn.getResponseCode();
        if (code != 200) { conn.disconnect(); return null; }
        java.io.InputStream is = conn.getInputStream();
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf = new byte[4096];
        int n;
        while ((n = is.read(buf)) != -1) bos.write(buf, 0, n);
        is.close();
        conn.disconnect();
        return bos.toString("UTF-8");
    } catch (Exception e) { return null; }
}

String jdyHttpGetWithHeaders(String urlStr, String[][] headers) {
    try {
        java.net.URL u = new java.net.URL(urlStr);
        java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
        conn.setConnectTimeout(8000);
        conn.setReadTimeout(8000);
        conn.setRequestMethod("GET");
        if (headers != null) {
            for (int i = 0; i < headers.length; i++) conn.setRequestProperty(headers[i][0], headers[i][1]);
        }
        int code = conn.getResponseCode();
        if (code != 200) { conn.disconnect(); return null; }
        java.io.InputStream is = conn.getInputStream();
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf = new byte[4096];
        int n;
        while ((n = is.read(buf)) != -1) bos.write(buf, 0, n);
        is.close();
        conn.disconnect();
        return bos.toString("UTF-8");
    } catch (Exception e) { return null; }
}

boolean jdyDownloadFile(String urlStr, String savePath) {
    try {
        java.net.URL u = new java.net.URL(urlStr);
        java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
        conn.setConnectTimeout(15000);
        conn.setReadTimeout(15000);
        conn.setRequestMethod("GET");
        int code = conn.getResponseCode();
        if (code != 200) { conn.disconnect(); return false; }
        java.io.InputStream is = conn.getInputStream();
        java.io.FileOutputStream fos = new java.io.FileOutputStream(savePath);
        byte[] buf = new byte[8192];
        int n;
        while ((n = is.read(buf)) != -1) fos.write(buf, 0, n);
        fos.close();
        is.close();
        conn.disconnect();
        return true;
    } catch (Exception e) { return false; }
}

JSONObject jdyParseJson(String s) {
    try { return new JSONObject(s); } catch (Exception e) { return null; }
}

String jdyJsonStr(JSONObject o, String k) {
    if (o == null) return "";
    return o.optString(k, "");
}

int jdyJsonInt(JSONObject o, String k) {
    if (o == null) return 0;
    return o.optInt(k, 0);
}

JSONObject jdyJsonObj(JSONObject o, String k) {
    if (o == null) return null;
    return o.optJSONObject(k);
}

JSONArray jdyJsonArr(JSONObject o, String k) {
    if (o == null) return null;
    return o.optJSONArray(k);
}

// ===== XKR 作用域管理 =====
boolean jdyIsInScope(Set<String> scopeSet, String talker) {
    if (scopeSet == null || scopeSet.isEmpty()) return true;
    if (scopeSet.contains(talker)) return true;
    if (talker != null && talker.contains("@")) {
        return scopeSet.contains(talker.substring(0, talker.indexOf("@")));
    }
    return false;
}

boolean jdyCheckFeatureScope(String feature, String talker, boolean isGroup) {
    if (isGroup) {
        final Set<String> scope;
        if (feature.equals("weather")) scope = jdyWeatherScope;
        else if (feature.equals("music")) scope = jdyMusicScope;
        else if (feature.equals("lyrics")) scope = jdyLyricsScope;
        else if (feature.equals("joke")) scope = jdyJokeScope;
        else if (feature.equals("dingdong")) scope = jdyDingdongScope;
        else return true;
        return jdyIsInScope(scope, talker);
    }
    return true;
}

void jdySaveScope(String configKey, Set<String> scopeSet) {
    if (scopeSet == null || scopeSet.isEmpty()) { putString(configKey, ""); return; }
    StringBuilder sb = new StringBuilder();
    boolean first = true;
    for (String s : scopeSet) {
        if (!first) sb.append(",");
        sb.append(s);
        first = false;
    }
    putString(configKey, sb.toString());
}

void jdyLoadScope(String configKey, Set<String> scopeSet) {
    scopeSet.clear();
    String saved = getString(configKey, "");
    if (saved == null || saved.isEmpty()) return;
    String[] parts = saved.split(",");
    for (String p : parts) { p = p.trim(); if (!p.isEmpty()) scopeSet.add(p); }
}

java.util.List<String[]> jdyGetCachedGroups() {
    long now = System.currentTimeMillis();
    if (jdyCachedGroups != null && (now - jdyCachedGroupsTime) < 60000) return jdyCachedGroups;
    jdyCachedGroups = getGroupListForSelect();
    jdyCachedGroupsTime = now;
    log("[Scope] jdyGetCachedGroups: " + jdyCachedGroups.size() + " groups");
    return jdyCachedGroups;
}

java.util.List<String[]> jdyGetCachedFriends() {
    long now = System.currentTimeMillis();
    if (jdyCachedFriends != null && (now - jdyCachedFriendsTime) < 60000) return jdyCachedFriends;
    jdyCachedFriends = getFriendListForSelect();
    jdyCachedFriendsTime = now;
    log("[Scope] jdyGetCachedFriends: " + jdyCachedFriends.size() + " friends");
    return jdyCachedFriends;
}

