boolean jdyIsPasswordUsed(int idx) {
    try {
        String used = getString("jdy_pwd_used", "");
        if (used.isEmpty()) return false;
        String[] parts = used.split(",");
        for (int i = 0; i < parts.length; i++) {
            if (parts[i].equals(String.valueOf(idx))) return true;
        }
    } catch (Exception e) {}
    return false;
}

void jdyMarkPasswordUsed(int idx) {
    try {
        String used = getString("jdy_pwd_used", "");
        if (used.isEmpty()) used = String.valueOf(idx);
        else used = used + "," + idx;
        putString("jdy_pwd_used", used);
    } catch (Exception e) {}
}

long jdyTempPasswordCreatedAt() {
    long ts = getLong("jdy_temp_created_at", 0);
    if (ts == 0) {
        ts = System.currentTimeMillis();
        putLong("jdy_temp_created_at", ts);
    }
    return ts;
}

