void jdyTtsToVoice(final String text, final String talker) {
    exec(new Runnable() {
        public void run() {
            try {
                String engine = currentTtsEngine;
                if (engine == null) engine = "";
                String audioUrl = null;

                if ("peiyinmofang".equals(engine) && peiyinApiKey != null && !peiyinApiKey.isEmpty() && !peiyinVoiceId.isEmpty()) {
                    java.net.URL u = new java.net.URL("https://peiyinmofang.com/api/open/v1/tts/simple-generate");
                    java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
                    conn.setRequestMethod("POST");
                    conn.setConnectTimeout(15000); conn.setReadTimeout(20000);
                    conn.setDoOutput(true);
                    conn.setRequestProperty("Content-Type", "application/json");
                    conn.setRequestProperty("Authorization", "Bearer " + peiyinApiKey);
                    java.util.Map reqMap = new java.util.HashMap();
                    reqMap.put("voiceId", peiyinVoiceId);
                    reqMap.put("text", text);
                    String reqBody = new org.json.JSONObject(reqMap).toString();
                    java.io.OutputStream os = conn.getOutputStream();
                    os.write(reqBody.getBytes("UTF-8")); os.flush(); os.close();
                    if (conn.getResponseCode() == 200) {
                        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
                        StringBuilder sb = new StringBuilder(); String l;
                        while ((l = br.readLine()) != null) sb.append(l);
                        br.close();
                        org.json.JSONObject rj = new org.json.JSONObject(sb.toString());
                        if (rj.optInt("status") == 200) {
                            org.json.JSONObject d = rj.optJSONObject("data");
                            if (d != null) audioUrl = d.optString("audio", "");
                        }
                    }
                    conn.disconnect();
                } else if ("wusound".equals(engine) && wusoundApiKey != null && !wusoundApiKey.isEmpty() && !wusoundVoiceId.isEmpty()) {
                    java.net.URL u = new java.net.URL("https://v1.wusound.cn/api/tts/simple-generate");
                    java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
                    conn.setRequestMethod("POST");
                    conn.setConnectTimeout(15000); conn.setReadTimeout(20000);
                    conn.setDoOutput(true);
                    conn.setRequestProperty("Content-Type", "application/json");
                    conn.setRequestProperty("Authorization", "Bearer " + wusoundApiKey);
                    java.util.Map reqMap = new java.util.HashMap();
                    reqMap.put("voiceId", wusoundVoiceId);
                    reqMap.put("text", text);
                    reqMap.put("promptId", wusoundPromptId);
                    reqMap.put("preset", "balance");
                    reqMap.put("break_clone", true);
                    reqMap.put("language", "auto");
                    String reqBody = new org.json.JSONObject(reqMap).toString();
                    java.io.OutputStream os = conn.getOutputStream();
                    os.write(reqBody.getBytes("UTF-8")); os.flush(); os.close();
                    if (conn.getResponseCode() == 200) {
                        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
                        StringBuilder sb = new StringBuilder(); String l;
                        while ((l = br.readLine()) != null) sb.append(l);
                        br.close();
                        org.json.JSONObject rj = new org.json.JSONObject(sb.toString());
                        if (rj.optInt("status") == 200) {
                            org.json.JSONObject d = rj.optJSONObject("data");
                            if (d != null) audioUrl = d.optString("audio", "");
                        }
                    }
                    conn.disconnect();
                }

                if (audioUrl == null || audioUrl.isEmpty()) {
                    mainHandler.post(new Runnable() { public void run() { toast("TTS合成失败，请检查语音引擎配置"); } });
                    return;
                }
                if (talker == null || talker.isEmpty()) { return; }

                java.net.HttpURLConnection dc = (java.net.HttpURLConnection) new java.net.URL(audioUrl).openConnection();
                dc.setConnectTimeout(15000); dc.setReadTimeout(20000);
                java.io.InputStream is = dc.getInputStream();
                String savePath = cacheDir + "/tts_" + System.currentTimeMillis() + ".mp3";
                java.io.FileOutputStream fos = new java.io.FileOutputStream(savePath);
                byte[] buf = new byte[8192]; int len;
                while ((len = is.read(buf)) != -1) fos.write(buf, 0, len);
                fos.flush(); fos.close(); is.close(); dc.disconnect();

                String silkPath = savePath + ".silk";
                mp3ToSilk(savePath, silkPath);
                sendVoice(talker, silkPath);

                mainHandler.post(new Runnable() { public void run() { toast("语音消息已发送"); } });
            } catch (Exception e) {
                log("jdyTtsToVoice: " + e.getMessage());
                mainHandler.post(new Runnable() { public void run() { toast("TTS发送失败: " + e.getMessage()); } });
            }
        }
    });
}

