// Base64 encoder for wxid-to-avatar matching
String toBase64(String input) {
    try {
        byte[] data = input.getBytes("UTF-8");
        return android.util.Base64.encodeToString(data, android.util.Base64.NO_WRAP);
    } catch (Exception e) { return null; }
}

// debugLog adapter
void debugLog(String msg) {
    try { log(msg); } catch (Exception e) {}
}

// loadScope adapter (comma-separated format)
java.util.List<String> loadScope(String scopeKey) {
    java.util.List<String> list = new java.util.ArrayList<>();
    try {
        String raw = getString(scopeKey, "");
        if (raw != null && raw.length() > 0) {
            String[] parts = raw.split(",");
            for (int i = 0; i < parts.length; i++) {
                String p = parts[i].trim();
                if (p.length() > 0) list.add(p);
            }
        }
    } catch (Exception e) {
        try { log("loadScope error: " + e.getMessage()); } catch (Exception ex) {}
    }
    return list;
}

// saveScope adapter (comma-separated format)
void saveScope(String scopeKey, java.util.List<String> list) {
    try {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < list.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append(list.get(i));
        }
        putString(scopeKey, sb.toString());
    } catch (Exception e) {
        try { log("saveScope error: " + e.getMessage()); } catch (Exception ex) {}
    }
}

