// --- isDarkMode ---
boolean isDarkMode() {
    long now = System.currentTimeMillis();
    if (_darkModeCached && (now - _darkModeCacheTime) < 3000) return _darkModeCached;
    try {
        Object config = callGetter(getTopActivity(), "getResources");
        if (config != null) {
            Object cfg = callGetter(config, "getConfiguration");
            if (cfg != null) {
                int uiMode = getFieldInt(cfg, "uiMode");
                _darkModeCached = (uiMode & 0x30) == 0x20;
                _darkModeCacheTime = now;
                return _darkModeCached;
            }
        }
    } catch (Exception e) {}
    _darkModeCached = false;
    _darkModeCacheTime = now;
    return false;
}

// --- updateSwitchVisual ---
void updateSwitchVisual(android.widget.TextView indicator, boolean isOn) {
    if (isOn) {
        indicator.setText("\u2713");
        indicator.setTextColor(c("FF" + thWhite()));
        indicator.setTextSize(14f);
        try { indicator.getPaint().setFakeBoldText(true); } catch (Exception e) {}
        GradientDrawable gd = new GradientDrawable();
        gd.setOrientation(GradientDrawable.Orientation.LEFT_RIGHT);
        gd.setColors(new int[]{c("FF" + thAccent2()), c("FF" + thAccent())});
        gd.setCornerRadius(dp(13));
        indicator.setBackground(gd);
    } else {
        indicator.setText("\u2717");
        indicator.setTextColor(c("FF" + thText2()));
        indicator.setTextSize(14f);
        GradientDrawable gd = new GradientDrawable();
        gd.setCornerRadius(dp(13));
        gd.setStroke(dp(1), c("FF" + thBorder()));
        gd.setColor(Color.TRANSPARENT);
        indicator.setBackground(gd);
    }
}

// --- startGentleFlow ---
void startGentleFlow(final GradientDrawable gd, final android.app.Dialog dialog) {
    try {
        final android.os.Handler h = new android.os.Handler(android.os.Looper.getMainLooper());
        h.postDelayed(new Runnable() {
            int step = 0;
            public void run() {
                try {
                    if (!dialog.isShowing()) return;
                    boolean dark = isDarkMode();
                    int[][] gradients;
                    if (dark) {
                        gradients = new int[][]{
                            {c("FF" + thAccent()), c("FF" + thRed())},
                            {c("FF" + thAccent2()), c("FF" + thAccent())},
                            {c("FF" + thRed()), c("FF" + thAccent2())},
                            {c("FF" + thAccent()), c("FF" + thRed())}
                        };
                    } else {
                        gradients = new int[][]{
                            {c("FF" + thAccent()), c("FF" + thAccent2())},
                            {c("FF" + thAccent2()), c("FF" + thAccent())},
                            {c("FF" + thAccent2()), c("FF" + thAccent2())},
                            {c("FF" + thAccent()), c("FF" + thAccent2())}
                        };
                    }
                    int idx = step % gradients.length;
                    gd.setColors(new int[]{gradients[idx][0], gradients[idx][1]});
                    step++;
                    h.postDelayed(this, 3000);
                } catch (Exception e) {}
            }
        }, 3000);
    } catch (Exception e) {}
}

// --- addBtnClickAnim ---
void addBtnClickAnim(final View view) {
    view.setOnTouchListener(new View.OnTouchListener() {
        public boolean onTouch(View v, android.view.MotionEvent event) {
            try {
                switch (event.getAction()) {
                    case android.view.MotionEvent.ACTION_DOWN:
                        v.animate().scaleX(0.95f).scaleY(0.95f).setDuration(100).start();
                        break;
                    case android.view.MotionEvent.ACTION_UP:
                    case android.view.MotionEvent.ACTION_CANCEL:
                        v.animate().scaleX(1.0f).scaleY(1.0f).setDuration(100).start();
                        break;
                }
            } catch (Exception e) {}
            return false;
        }
    });
}

