// --- createCheckItem ---
LinearLayout createCheckItem(android.content.Context ctx, String label, boolean checked) {
    LinearLayout row = new LinearLayout(ctx);
    row.setOrientation(LinearLayout.HORIZONTAL);
    row.setGravity(android.view.Gravity.CENTER_VERTICAL);
    row.setTag(new boolean[]{checked});
    row.setClickable(true);

    TextView indicator = new TextView(ctx);
    indicator.setGravity(android.view.Gravity.CENTER);
    indicator.setLayoutParams(new LinearLayout.LayoutParams(dp(26), dp(26)));
    updateSwitchVisual(indicator, checked);
    row.addView(indicator);

    TextView nameTv = new TextView(ctx);
    nameTv.setText(label);
    nameTv.setTextColor(c(thCard()));
    nameTv.setTextSize(14f);
    nameTv.setPadding(dp(10), 0, 0, 0);
    row.addView(nameTv);

    row.setOnClickListener(new View.OnClickListener() {
        public void onClick(View v) {
            try {
                Object tag = v.getTag();
                if (tag instanceof boolean[]) {
                    boolean[] st = (boolean[]) tag;
                    st[0] = !st[0];
                    LinearLayout r = (LinearLayout) v;
                    View ind = r.getChildAt(0);
                    if (ind instanceof TextView) {
                        updateSwitchVisual((TextView) ind, st[0]);
                    }
                }
            } catch (Exception e) {}
        }
    });
    addBtnClickAnim(row);
    return row;
}

// --- getCheckItemState ---
boolean[] getCheckItemState(LinearLayout checkItem) {
    Object tag = checkItem.getTag();
    if (tag instanceof boolean[]) return (boolean[]) tag;
    return new boolean[]{false};
}

// --- isCheckItemChecked ---
boolean isCheckItemChecked(LinearLayout checkItem) {
    return getCheckItemState(checkItem)[0];
}

// --- setCheckItemChecked ---
void setCheckItemChecked(LinearLayout checkItem, boolean checked) {
    getCheckItemState(checkItem)[0] = checked;
}

// --- setCheckItemState ---
void setCheckItemState(LinearLayout checkItem, boolean checked) {
    Object tag = checkItem.getTag();
    if (tag instanceof boolean[]) {
        ((boolean[]) tag)[0] = checked;
    } else {
        checkItem.setTag(new boolean[]{checked});
    }
    try {
        View ind = checkItem.getChildAt(0);
        if (ind instanceof TextView) {
            updateSwitchVisual((TextView) ind, checked);
        }
    } catch (Exception e) {}
}

// --- isInScope ---
boolean isInScope(String scopeKey, String talker) {
    if (TextUtils.isEmpty(talker)) return false;
    java.util.List<String> whitelist = loadScope(scopeKey);
    java.util.List<String> blacklist = loadScope(scopeKey + "_blacklist");
    if (!blacklist.isEmpty() && blacklist.contains(talker)) return false;
    if (whitelist.isEmpty()) return true;
    return whitelist.contains(talker);
}

// --- saveScope (provided by adapter above) ---

// --- toggleChatScope ---
void toggleChatScope(String scopeKey, String chatId) {
    java.util.List<String> list = loadScope(scopeKey);
    if (list.contains(chatId)) {
        list.remove(chatId);
    } else {
        list.add(chatId);
    }
    saveScope(scopeKey, list);
}

// --- getScopeDisplay ---
String getScopeDisplay(String scopeKey) {
    java.util.List<String> list = loadScope(scopeKey);
    java.util.List<String> bl = loadScope(scopeKey + "_blacklist");
    if (list.isEmpty() && bl.isEmpty()) return "所有人";
    if (list.isEmpty()) return "排除" + bl.size();
    return list.size() + "个";
}

// --- compatNames ---
String[] compatNames(String fieldName) {
    // Try snake_case and camelCase variants
    String camel = fieldName;
    if (camel.contains("_")) {
        StringBuilder sb = new StringBuilder();
        boolean up = false;
        for (int i = 0; i < camel.length(); i++) {
            char c = camel.charAt(i);
            if (c == '_') { up = true; continue; }
            sb.append(up ? Character.toUpperCase(c) : c);
            up = false;
        }
        camel = sb.toString();
    }
    // Gen both original and m-prefixed for WeChat's obfuscated fields
    return new String[]{fieldName, camel, "m" + Character.toUpperCase(camel.charAt(0)) + camel.substring(1)};
}

// --- compatGetter ---
String[] compatGetter(String fieldName) {
    String cap = Character.toUpperCase(fieldName.charAt(0)) + fieldName.substring(1);
    // For boolean fields, try isXxx and getXxx
    return new String[]{"get" + cap, "is" + cap, fieldName};
}

// --- getFieldString ---
String getFieldString(Object obj, String fieldName) {
    try {
        if (obj == null) return "";
        java.lang.reflect.Field f = findField(obj.getClass(), fieldName);
        if (f == null) return "";
        f.setAccessible(true);
        Object val = f.get(obj);
        return val != null ? val.toString() : "";
    } catch (Exception e) { return ""; }
}

// --- getFieldInt ---
int getFieldInt(Object obj, String fieldName) {
    try {
        if (obj == null) return 0;
        java.lang.reflect.Field f = findField(obj.getClass(), fieldName);
        if (f == null) return 0;
        f.setAccessible(true);
        Object val = f.get(obj);
        if (val instanceof Number) return ((Number) val).intValue();
        return 0;
    } catch (Exception e) { return 0; }
}

// --- callGetter ---
Object callGetter(Object obj, String fieldName) {
    try {
        if (obj == null) return null;
        String[] names = compatGetter(fieldName);
        for (int i = 0; i < names.length; i++) {
            try {
                java.lang.reflect.Method m = obj.getClass().getMethod(names[i]);
                return m.invoke(obj);
            } catch (NoSuchMethodException e) { continue; }
        }
    } catch (Exception e) {}
    return null;
}

// --- tryCallMethod ---
Object tryCallMethod(String methodName) {
    try {
        java.lang.reflect.Method m = this.getClass().getMethod(methodName);
        return m.invoke(this);
    } catch (Exception e) { return null; }
}

// --- tryCallMethodWithArg ---
Object tryCallMethodWithArg(String methodName, Object arg) {
    try {
        java.lang.reflect.Method m = this.getClass().getMethod(methodName, arg.getClass());
        return m.invoke(this, arg);
    } catch (Exception e) { return null; }
}

// --- getNickByFields ---
String getNickByFields(Object obj) {
    String[] fields = {"nickname", "nickName", "name", "displayName", "remark", "alias"};
    for (int i = 0; i < fields.length; i++) {
        String v = getFieldString(obj, fields[i]);
        if (!TextUtils.isEmpty(v) && !v.equals("null")) return v;
    }
    return "";
}

