// --- findAvatarAndNickInList ---
String[] findAvatarAndNickInList(Object listObj, String targetId) {
    try {
        if (listObj == null || TextUtils.isEmpty(targetId)) return new String[]{null, ""};
        java.util.List list = null;
        if (listObj instanceof java.util.Map) {
            list = new java.util.ArrayList(((java.util.Map) listObj).values());
        } else if (listObj instanceof java.util.List) {
            list = (java.util.List) listObj;
        }
        if (list == null) return new String[]{null, ""};
        for (Object item : list) {
            if (item == null) continue;
            String id = getFieldString(item, "wxid");
            if (TextUtils.isEmpty(id)) id = getFieldString(item, "username");
            if (TextUtils.isEmpty(id)) id = getFieldString(item, "id");
            if (targetId.equals(id)) {
                String avatar = getAvatarUrlByReflection(item);
                String nick = getNickByFields(item);
                return new String[]{avatar, nick};
            }
        }
    } catch (Exception e) {}
    return new String[]{null, ""};
}

// --- findAvatarInList ---
String findAvatarInList(Object listObj, String targetId) {
    return findAvatarAndNickInList(listObj, targetId)[0];
}

// --- getAvatarUrlByReflection ---
String getAvatarUrlByReflection(Object obj) {
    try {
        if (obj == null) return null;
        String[] fields = {"avatar", "avatarUrl", "headImgUrl", "headUrl", "headimg", "headImg", "bigHeadImgUrl", "smallHeadImgUrl", "mBigHeadImgUrl", "mSmallHeadImgUrl"};
        for (int i = 0; i < fields.length; i++) {
            try {
                Object val = callGetter(obj, fields[i]);
                if (val != null) {
                    String s = val.toString();
                    if (!TextUtils.isEmpty(s) && s.length() > 10 && (s.startsWith("http") || s.startsWith("/"))) return s;
                }
            } catch (Exception e) {}
        }
        for (int i = 0; i < fields.length; i++) {
            try {
                String v = getFieldString(obj, fields[i]);
                if (!TextUtils.isEmpty(v) && v.length() > 10) return v;
            } catch (Exception e) {}
        }
    } catch (Exception e) {}
    return null;
}

// --- getGroupAvatarUrl ---
String getGroupAvatarUrl(String groupId) {
    try {
        if (TextUtils.isEmpty(groupId)) return null;
        // Step 1: Find in avatar directory cache
        if (sAvatarDir != null) {
            java.io.File ad = new java.io.File(sAvatarDir);
            if (ad.exists()) {
                java.io.File[] files = ad.listFiles();
                if (files != null) {
                    for (int i = 0; i < files.length; i++) {
                        String fn = files[i].getName();
                        if (fn.contains(groupId) || groupId.contains(fn.replace("_", "").replace(".jpg", "").replace(".png", ""))) {
                            return files[i].getAbsolutePath();
                        }
                    }
                }
            }
        }
        // Step 2: Find in group list via reflection
        Object gl = null;
        try { gl = getGroupList(); } catch (Exception e1) { try { gl = tryCallMethod("getGroupList"); } catch (Exception e2) {} }
        if (gl != null) {
            String url = findAvatarInList(gl, groupId);
            if (!TextUtils.isEmpty(url)) return url;
        }
        // Step 3: Check cached groups
        if (cachedGroups != null) {
            for (int i = 0; i < cachedGroups.size(); i++) {
                String[] g = cachedGroups.get(i);
                if (g != null && g.length >= 1 && groupId.equals(g[0])) return getAvatarUrlByReflection(g);
            }
        }
    } catch (Exception e) {}
    return null;
}

// --- getFriendAvatarUrl ---
String getFriendAvatarUrl(String wxid) {
    return getFriendAvatarUrl(wxid, false);
}

String getFriendAvatarUrl(String wxid, boolean fastMode) {
    try {
        if (TextUtils.isEmpty(wxid)) return null;
        // Step 1: Find in friend list (always try, reflection-based)
        Object fl = null;
        try { fl = getFriendList(); } catch (Exception e1) { try { fl = tryCallMethod("getFriendList"); } catch (Exception e2) {} }
        if (fl != null) {
            String url = findAvatarInList(fl, wxid);
            if (!TextUtils.isEmpty(url)) return url;
        }
        // Step 2: Avatar cache dir
        if (sAvatarDir != null) {
            java.io.File ad = new java.io.File(sAvatarDir);
            if (ad.exists()) {
                java.io.File[] files = ad.listFiles();
                String base64 = toBase64(wxid);
                if (files != null) {
                    for (int i = 0; i < files.length; i++) {
                        String fn = files[i].getName();
                        if (fn.contains(wxid) || (base64 != null && fn.contains(base64))) {
                            return files[i].getAbsolutePath();
                        }
                    }
                }
            }
        }
        // Step 3: Check cached friends
        if (cachedFriends != null) {
            for (int i = 0; i < cachedFriends.size(); i++) {
                String[] f = cachedFriends.get(i);
                if (f != null && f.length >= 1 && wxid.equals(f[0])) return getAvatarUrlByReflection(f);
            }
        }
    } catch (Exception e) {}
    return null;
}

// --- findField ---
java.lang.reflect.Field findField(Class clazz, String name) throws NoSuchFieldException {
    String[] names = compatNames(name);
    Class c = clazz;
    while (c != null) {
        for (int i = 0; i < names.length; i++) {
            try { return c.getDeclaredField(names[i]); } catch (NoSuchFieldException ignore) {}
        }
        c = c.getSuperclass();
    }
    throw new NoSuchFieldException(name);
}

