// --- getCachedGroups ---
java.util.List<String[]> getCachedGroups() {
    long now = System.currentTimeMillis();
    if (cachedGroups != null && (now - cachedGroupsTime) < CACHE_VALID_MS) {
        return cachedGroups;
    }
    cachedGroups = getGroupListForSelect();
    cachedGroupsTime = now;
    return cachedGroups;
}

// --- getCachedFriends ---
java.util.List<String[]> getCachedFriends() {
    long now = System.currentTimeMillis();
    if (cachedFriends != null && (now - cachedFriendsTime) < CACHE_VALID_MS) {
        return cachedFriends;
    }
    cachedFriends = getFriendListForSelect();
    cachedFriendsTime = now;
    return cachedFriends;
}

// --- preloadContacts ---
void preloadContacts() {
    exec(new Runnable() {
        public void run() {
            try {
                long now = System.currentTimeMillis();
                if (cachedGroups == null || (now - cachedGroupsTime) > CACHE_VALID_MS) {
                    cachedGroups = getGroupListForSelect();
                    cachedGroupsTime = now;
                }
                if (cachedFriends == null || (now - cachedFriendsTime) > CACHE_VALID_MS) {
                    cachedFriends = getFriendListForSelect();
                    cachedFriendsTime = now;
                }
            } catch (Exception e) {
                debugLog("[Preload] error: " + e.getMessage());
            }
        }
    });
}

// --- buildMusicCardXml ---
String buildMusicCardXml(String title, String artist, String coverUrl, String playUrl, String jumpUrl, String source, String wxid) {
    try {
        StringBuilder xml = new StringBuilder();
        xml.append("<msg>");
        xml.append("<appmsg appid=\"wx79f2c4418704b4f8\" sdkver=\"0\">");
        xml.append("<title>").append(escXml(title)).append("</title>");
        xml.append("<des>").append(escXml(artist)).append("</des>");
        xml.append("<type>3</type>");
        xml.append("<action>view</action>");
        xml.append("<url>").append(escXml(jumpUrl)).append("</url>");
        xml.append("<thumburl>").append(escXml(coverUrl)).append("</thumburl>");
        xml.append("<appattach>");
        xml.append("<cdnthumburl>").append(escXml(coverUrl)).append("</cdnthumburl>");
        xml.append("<cdnthumblength>0</cdnthumblength>");
        xml.append("<cdnthumbwidth>200</cdnthumbwidth>");
        xml.append("<cdnthumbheight>200</cdnthumbheight>");
        if (!TextUtils.isEmpty(playUrl)) {
            xml.append("<songlyric></songlyric>");
            xml.append("<songalbumurl>").append(escXml(coverUrl)).append("</songalbumurl>");
            xml.append("<songalbumurl1_1>").append(escXml(coverUrl)).append("</songalbumurl1_1>");
        }
        xml.append("</appattach>");
        xml.append("<appinfo>");
        xml.append("<appname>").append(escXml(source)).append("</appname>");
        xml.append("</appinfo>");
        xml.append("</appmsg>");
        xml.append("</msg>");
        return xml.toString();
    } catch (Exception e) {
        return "<msg><appmsg><title>" + escXml(title) + "</title><des>" + escXml(artist) + "</des><type>3</type></appmsg></msg>";
    }
}

String escXml(String s) {
    if (s == null) return "";
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&apos;");
}

// --- getImageBytesQuick ---
byte[] getImageBytesQuick(String url) {
    try {
        java.net.URL u = new java.net.URL(url);
        java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
        conn.setConnectTimeout(3000);
        conn.setReadTimeout(3000);
        conn.setRequestMethod("GET");
        int code = conn.getResponseCode();
        if (code != 200) { conn.disconnect(); return null; }
        java.io.InputStream is = conn.getInputStream();
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        byte[] buf = new byte[4096];
        int n;
        while ((n = is.read(buf)) != -1) bos.write(buf, 0, n);
        is.close();
        conn.disconnect();
        return bos.toByteArray();
    } catch (Exception e) { return null; }
}

// --- getImageBytes ---
byte[] getImageBytes(String imageUrl) {
    byte[] result = getImageBytesQuick(imageUrl);
    if (result != null) return result;
    try {
        if (imageUrl.startsWith("http://")) {
            String httpsUrl = "https" + imageUrl.substring(4);
            return getImageBytesQuick(httpsUrl);
        }
    } catch (Exception e) {}
    return null;
}

// --- compressImageToThumb ---
byte[] compressImageToThumb(byte[] rawData) {
    try {
        if (rawData == null || rawData.length == 0) return null;
        android.graphics.BitmapFactory.Options opts = new android.graphics.BitmapFactory.Options();
        opts.inJustDecodeBounds = true;
        android.graphics.BitmapFactory.decodeByteArray(rawData, 0, rawData.length, opts);
        int w = opts.outWidth, h = opts.outHeight;
        if (w <= 0 || h <= 0) return null;
        int maxDim = 200;
        int sampleSize = 1;
        while (w / sampleSize > maxDim || h / sampleSize > maxDim) sampleSize *= 2;
        opts.inJustDecodeBounds = false;
        opts.inSampleSize = sampleSize;
        opts.inPreferredConfig = android.graphics.Bitmap.Config.RGB_565;
        android.graphics.Bitmap bmp = android.graphics.BitmapFactory.decodeByteArray(rawData, 0, rawData.length, opts);
        if (bmp == null) return null;
        if (bmp.getWidth() > maxDim || bmp.getHeight() > maxDim) {
            float ratio = Math.min((float) maxDim / bmp.getWidth(), (float) maxDim / bmp.getHeight());
            int newW = Math.round(bmp.getWidth() * ratio);
            int newH = Math.round(bmp.getHeight() * ratio);
            android.graphics.Bitmap scaled = android.graphics.Bitmap.createScaledBitmap(bmp, newW, newH, true);
            bmp.recycle();
            bmp = scaled;
        }
        java.io.ByteArrayOutputStream bos = new java.io.ByteArrayOutputStream();
        bmp.compress(android.graphics.Bitmap.CompressFormat.JPEG, 70, bos);
        bmp.recycle();
        return bos.toByteArray();
    } catch (Exception e) {
        debugLog("[Compress] error: " + e.getMessage());
        return null;
    }
}

// --- downloadCoverForMusic ---
byte[] downloadCoverForMusic(String url) {
    try {
        if (TextUtils.isEmpty(url)) return null;
        byte[] raw = getImageBytes(url);
        if (raw == null) return null;
        if (raw.length > 10240) {
            byte[] thumb = compressImageToThumb(raw);
            if (thumb != null) return thumb;
        }
        return raw;
    } catch (Exception e) {
        debugLog("[Cover] download error: " + e.getMessage());
        return null;
    }
}

// --- sendSingleMusicCardWithSource ---
boolean sendSingleMusicCardWithSource(String talker, String title, String artist, String coverUrl, String playUrl, String jumpUrl, String source, String wxid) {
    try {
        String xml = buildMusicCardXml(title, artist, coverUrl, playUrl, jumpUrl, source, wxid);
        if (TextUtils.isEmpty(xml)) return false;
        // Try to send as music appmsg
        try {
            java.lang.reflect.Method m = this.getClass().getMethod("sendAppMsg", String.class, String.class, String.class, String.class, String.class);
            if (m != null) {
                m.invoke(this, talker, xml, title, artist, coverUrl);
                return true;
            }
        } catch (Exception e) {}
        // Fallback: send as text XML
        try {
            java.lang.reflect.Method m2 = this.getClass().getMethod("sendMsg", String.class, String.class);
            if (m2 != null) {
                m2.invoke(this, talker, xml);
                return true;
            }
        } catch (Exception e2) {}
    } catch (Exception e) {
        debugLog("[MusicCard] send error: " + e.getMessage());
    }
    return false;
}

// --- tryRevokeMsg ---
void tryRevokeMsg(String talker, String msgId) {
    try {
        if (TextUtils.isEmpty(talker) || TextUtils.isEmpty(msgId)) return;
        // Wait briefly then try to revoke
        exec(new Runnable() {
            public void run() {
                try {
                    Thread.sleep(3000);
                } catch (InterruptedException e) {}
                try {
                    java.lang.reflect.Method m = this.getClass().getEnclosingClass().getDeclaredMethod("sendRevokeMsg", String.class, String.class);
                    if (m != null) {
                        m.setAccessible(true);
                        m.invoke(this.getClass().getEnclosingClass().newInstance(), talker, msgId);
                    }
                } catch (Exception e) {
                    debugLog("[Revoke] error: " + e.getMessage());
                }
            }
        });
    } catch (Exception e) {
        debugLog("[Revoke] init error: " + e.getMessage());
    }
}

