    final boolean[] localAnnounceNickname = {announceNickname};
    final boolean[] localAnnounceGroup = {announceGroup};
    final boolean[] localAnnounceCall = {announceCall};
    final boolean[] localAnnounceLocation = {announceLocation};
    final boolean[] localAnnounceDouyin = {announceDouyin};
    final List localWhitelist = new ArrayList(WHITE_LIST);

    android.widget.LinearLayout root = new android.widget.LinearLayout(c);
    root.setOrientation(1);
    root.setGravity(android.view.Gravity.CENTER);
    root.setPadding(dp(12), dp(8), dp(12), dp(8));
    root.setBackgroundDrawable(createGlassBg(0));

    // ========== 标题栏 ==========
    android.widget.LinearLayout titleRow = new android.widget.LinearLayout(c);
    titleRow.setOrientation(0);
    titleRow.setGravity(android.view.Gravity.CENTER);
    titleRow.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1, -2));
    titleRow.setPadding(dp(6), dp(6), dp(6), dp(6));
    titleRow.setBackgroundDrawable(createGlassBg(12));

    android.widget.TextView tvTitle = T(c, "乐少助手多功能版", 18, c("FF" + thAccent()), true);
    tvTitle.setGravity(android.view.Gravity.CENTER);
    titleRow.addView(tvTitle);

    root.addView(titleRow);

    // ========== 用户信息卡片 ==========
    {
        final android.widget.LinearLayout cardUserInfo = new android.widget.LinearLayout(c);
        cardUserInfo.setOrientation(0);
        cardUserInfo.setGravity(android.view.Gravity.CENTER_VERTICAL);
        cardUserInfo.setPadding(dp(7), dp(8), dp(7), dp(8));
        cardUserInfo.setBackgroundDrawable(createCardBg(10));

        final android.widget.ImageView ivAvatar = new android.widget.ImageView(c);
        android.widget.LinearLayout.LayoutParams avLp = new android.widget.LinearLayout.LayoutParams(dp(48), dp(48));
        avLp.rightMargin = dp(10);
        ivAvatar.setLayoutParams(avLp);
        ivAvatar.setScaleType(android.widget.ImageView.ScaleType.CENTER_CROP);
        cardUserInfo.addView(ivAvatar);

        android.widget.LinearLayout infoCol = new android.widget.LinearLayout(c);
        infoCol.setOrientation(1);
        infoCol.setGravity(android.view.Gravity.CENTER_VERTICAL);
        infoCol.setLayoutParams(new android.widget.LinearLayout.LayoutParams(0, -2, 1));

        final android.widget.TextView tvNick = T(c, "加载中...", 14, c("FF" + thText()), true);
        infoCol.addView(tvNick);

        String wxidStr = "";
        try { wxidStr = getLoginWxid(); } catch (Exception e) {}
        final String selfWxid = wxidStr;
        final String wxidDisplay = wxidStr.isEmpty() ? "未登录" : wxidStr;
        android.widget.TextView tvWxid = T(c, "微信号: " + wxidDisplay, 11, c("FF" + thText2()), false);
        tvWxid.setPadding(0, dp(2), 0, 0);
        infoCol.addView(tvWxid);

        String expFormat = activationExpiry;
        try {
            String[] parts = activationExpiry.split("-");
            expFormat = parts[0] + "年" + parts[1] + "月" + parts[2] + "日";
        } catch (Exception e) {}
        final android.widget.TextView tvExpiry = T(c, "有效期: " + expFormat, 11, c("FF" + thRed()), false);
        tvExpiry.setPadding(0, dp(1), 0, 0);
        infoCol.addView(tvExpiry);

        cardUserInfo.addView(infoCol);

        root.addView(cardUserInfo);

        exec(new Runnable() {
            public void run() {
                String selfNick = "";
                if (!selfWxid.isEmpty()) {
                    try {
                        Object fl = getFriendList();
                        if (fl != null) {
                            String[] info = findAvatarAndNickInList(fl, selfWxid);
                            if (info != null && info[1] != null && !info[1].isEmpty()) {
                                selfNick = info[1];
                            }
                        }
                    } catch (Exception e) {}
                }
                if (selfNick.isEmpty()) {
                    try { selfNick = getLoginAlias(); } catch (Exception e) {}
                }
                if (selfNick.isEmpty()) selfNick = "未登录";
                final String nick = selfNick;
                mainHandler.post(new Runnable() {
                    public void run() {
                        tvNick.setText(nick);
                    }
                });
            }
        });

        if (!selfWxid.isEmpty()) {
            loadAvatarAsync(ivAvatar, selfWxid);
        }
    }

    root.addView(SP(c, dp(3)));

    // ========== 模块总开关卡片 ==========
