    // ===== 功能开关 =====
    {
        android.widget.LinearLayout cardDG = new android.widget.LinearLayout(c);
        cardDG.setOrientation(1);
        cardDG.setPadding(dp(7), dp(4), dp(7), dp(4));
        cardDG.setBackgroundDrawable(createCardBg(10));

        android.widget.TextView tvMMLabel = T(c, "多媒体工具", 13, c("FF" + thAccent()), true);
        tvMMLabel.setGravity(Gravity.CENTER);
        tvMMLabel.setPadding(0, dp(3), 0, dp(4));
        cardDG.addView(tvMMLabel);

        String[][] ddFeatures = {
            {KEY_DD_VOICE_SONG, "语音点歌", "发送 '语音点歌 歌名' 搜索并播放"},
            {KEY_DD_VIDEO_AUDIO, "视频转语音", "发送 '提取语音 链接' 提取音频"},
            {KEY_DD_VIDEO_MSG, "视频下载", "发送 '下载视频 链接' 下载视频"}
        };

        for (String[] f : ddFeatures) {
            String ddKey = f[0]; String ddName = f[1]; String ddDesc = f[2];
            boolean ddOn = getBoolean(ddKey, true);

            android.widget.LinearLayout ddRow = new android.widget.LinearLayout(c);
            ddRow.setOrientation(0);
            ddRow.setGravity(Gravity.CENTER_VERTICAL);
            ddRow.setPadding(dp(6), dp(4), dp(6), dp(4));

            android.widget.LinearLayout ddTextCol = new android.widget.LinearLayout(c);
            ddTextCol.setOrientation(1);
            ddTextCol.setLayoutParams(new LinearLayout.LayoutParams(0, -2, 1));
            TextView ddNameTv = T(c, ddName, 13, c("FF" + thText()), true);
            ddTextCol.addView(ddNameTv);
            TextView ddDescTv = T(c, ddDesc, 10, c("FF" + thText2()), false);
            ddDescTv.setPadding(0, dp(1), 0, 0);
            ddTextCol.addView(ddDescTv);
            ddRow.addView(ddTextCol);

            Switch ddSw = new Switch(c);
            ddSw.setChecked(ddOn);
            styleSwitch(ddSw);
            ddSw.setTag(ddKey);
            ddSw.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {
                public void onCheckedChanged(CompoundButton btn, boolean checked) {
                    String key = (String) btn.getTag();
                    if (key != null) putBoolean(key, checked);
                }
            });
            ddRow.addView(ddSw);
            cardDG.addView(ddRow);
        }

        for (int dgi = 0; dgi < JDY_FEATURE_LIST.length; dgi++) {
            final String[] feat = JDY_FEATURE_LIST[dgi];
            final String featKey = feat[0];
            final String featScopeKey = feat[1];
            final String featName = feat[2];
            boolean dgOn = getBoolean(featKey, true);

            android.widget.LinearLayout dgRow = new android.widget.LinearLayout(c);
            dgRow.setOrientation(0);
            dgRow.setGravity(Gravity.CENTER_VERTICAL);
            dgRow.setPadding(dp(6), dp(4), dp(6), dp(4));

            android.widget.LinearLayout dgTextCol = new android.widget.LinearLayout(c);
            dgTextCol.setOrientation(1);
            dgTextCol.setLayoutParams(new LinearLayout.LayoutParams(0, -2, 0.7f));
            TextView dgNameTv = T(c, featName, 13, c("FF" + thText()), true);
            dgTextCol.addView(dgNameTv);
            String usg = feat.length > 3 ? feat[3] : null;
            if (usg != null && usg.length() > 0) {
                TextView usgTv = T(c, usg, 10, c("AA" + thText()), false);
                usgTv.setPadding(0, dp(2), 0, 0);
                dgTextCol.addView(usgTv);
            }
            dgRow.addView(dgTextCol);

            Switch dgSw = new Switch(c);
            dgSw.setChecked(dgOn);
            styleSwitch(dgSw);
            dgSw.setTag(featKey);
            dgSw.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {
                public void onCheckedChanged(CompoundButton btn, boolean checked) {
                    String key = (String) btn.getTag();
                    if (key != null) putBoolean(key, checked);
                }
            });
            dgRow.addView(dgSw);

            android.widget.Button scopeBtn = new android.widget.Button(c);
            scopeBtn.setText("范围");
            scopeBtn.setTextSize(10);
            scopeBtn.setAllCaps(false);
            scopeBtn.setTextColor(c("FF" + thWhite()));
            scopeBtn.setPadding(dp(6), dp(3), dp(6), dp(3));
            scopeBtn.setTag(featScopeKey + "|" + featName);
            GradientDrawable scopeBg = new GradientDrawable();
            scopeBg.setCornerRadius(dp(8));
            scopeBg.setColor(c("FF" + thAccent()));
            scopeBtn.setBackground(scopeBg);
            scopeBtn.setOnClickListener(new View.OnClickListener() {
                public void onClick(View v) {
                    String tag = (String) v.getTag();
                    if (tag == null) return;
                    int split = tag.indexOf("|");
                    if (split < 0) return;
                    final String scopeKey = tag.substring(0, split);
                    final String featName = tag.substring(split + 1);
                    showScopeDialog(scopeKey, featName, new Runnable() {
                        public void run() { toast("范围已保存: " + featName); }
                    });
                }
            });
            dgRow.addView(scopeBtn);
            cardDG.addView(dgRow);
        }

        root.addView(cardDG);
    }

    root.addView(SP(c, dp(3)));

    android.widget.LinearLayout bottomBar = new android.widget.LinearLayout(c);
    bottomBar.setOrientation(0);
