void jdyNavigateToFeature(String label, android.app.Dialog mainDlg) {
    if (mainDlg != null) { try { mainDlg.dismiss(); } catch (Exception e) {} }
    if (label.equals("天气")) { jdyShowWeatherPanel(); }
    else if (label.equals("歌词")) { jdyShowLyricsPanel(); }
    else if (label.equals("点歌")) { jdyShowMusicPanel(); }
    else if (label.equals("语音")) { jdyShowVoiceAudioPanel(); }
    else if (label.equals("视频")) { jdyShowVideoPanel(); }
    else if (label.equals("笑话")) { jdyShowJokePanel(); }
    else if (label.equals("金句")) { jdyShowQuotePanel(); }
    else if (label.equals("叮咚")) { jdyShowDingDongDialog(); jdyAddBackToMainButton(); }
    else if (label.equals("状态")) { jdyShowStatusDialog(); }
    else if (label.equals("帮助")) { jdyShowHelpDialog(); }
    else if (label.equals("TTS")) { jdyShowVoiceRelaySettingsPanel(); }
}

LinearLayout jdyBuildBackBar(final android.app.Activity act, String titleText, final android.app.Dialog currentDlg) {
    LinearLayout bar = new LinearLayout(act);
    bar.setOrientation(LinearLayout.HORIZONTAL);
    bar.setGravity(Gravity.CENTER_VERTICAL);
    bar.setPadding(dp(12), dp(8), dp(12), dp(8));

    Button btnBack = new Button(act);
    btnBack.setText("< 返回");
    btnBack.setTextSize(13);
    btnBack.setTextColor(c("FF" + thWhite()));
    btnBack.setAllCaps(false);
    btnBack.setPadding(dp(12), dp(5), dp(12), dp(5));
    GradientDrawable backBg = new GradientDrawable();
    backBg.setCornerRadius(dp(6));
    backBg.setColor(c(thAccent()));
    btnBack.setBackground(backBg);
    btnBack.setOnClickListener(new View.OnClickListener() {
        public void onClick(View v) {
            if (currentDlg != null) { try { currentDlg.dismiss(); } catch (Exception e) {} }
            showControlPanel();
        }
    });
    bar.addView(btnBack);

    TextView tvTitle = T(act, titleText, 16, c("FF" + thText()), true);
    tvTitle.setGravity(Gravity.CENTER);
    LinearLayout.LayoutParams tlp = new LinearLayout.LayoutParams(0, -2, 1);
    tlp.setMargins(dp(12), 0, 0, 0);
    bar.addView(tvTitle, tlp);
    return bar;
}

void jdyBuildSubDialog(LinearLayout content, String title) {
    android.app.Activity act = getTopActivity();
    if (act == null) { toast("无法获取顶层窗口"); return; }

    AlertDialog.Builder builder = new AlertDialog.Builder(act);
    final android.app.Dialog dialog = builder.create();

    LinearLayout root = new LinearLayout(act);
    root.setOrientation(LinearLayout.VERTICAL);
    root.setBackgroundDrawable(createGlassBg(0));

    root.addView(jdyBuildBackBar(act, title, dialog));

    ScrollView sv = new ScrollView(act);
    sv.addView(content);
    root.addView(sv, new LinearLayout.LayoutParams(-1, -2));

    Button btnClose = new Button(act);
    btnClose.setText("关闭");
    btnClose.setTextSize(14);
    btnClose.setTextColor(c("FF" + thWhite()));
    btnClose.setAllCaps(false);
    btnClose.setPadding(dp(20), dp(8), dp(20), dp(8));
    GradientDrawable closeBg = new GradientDrawable();
    closeBg.setCornerRadius(dp(8));
    closeBg.setColor(c("FF" + thRed()));
    btnClose.setBackground(closeBg);
    LinearLayout.LayoutParams blp = new LinearLayout.LayoutParams(-1, -2);
    blp.setMargins(dp(20), dp(8), dp(20), dp(12));
    btnClose.setLayoutParams(blp);
    btnClose.setOnClickListener(new View.OnClickListener() {
        public void onClick(View v) { try { dialog.dismiss(); } catch (Exception e) {} }
    });
    root.addView(btnClose);

    dialog.setContentView(root);
    dialog.setCancelable(true);
    dialog.setCanceledOnTouchOutside(true);
    dialog.show();
}

