// ================= 语音中继系统 (共用原有播报系统isSpeaking锁) =================

void jdyPollThenPlayVoice(String prefix, long voiceDuration) {
    String amrPath = null;
    for (int retry = 0; retry < 10; retry++) {
        try { Thread.sleep(retry == 0 ? 800 : 500); } catch (Exception e) {}
        amrPath = jdyGetRealLatestVoiceFile();
        if (amrPath != null && !jdyVoiceProcessedAmr.contains(amrPath)) {
            if (jdyVoiceProcessedAmr.size() > 50) jdyVoiceProcessedAmr.remove(0);
            jdyVoiceProcessedAmr.add(amrPath);
            break;
        }
    }
    if (amrPath == null) { log("[VoiceRelay] AMR file not found after retries"); return; }

    while (isSpeaking) {
        try { Thread.sleep(200); } catch (Exception e) {}
    }

    synchronized (messageQueue) {
        if (isSpeaking) return;
        isSpeaking = true;
    }

    if (prefix != null && prefix.length() > 0) {
        if (tts != null) {
            tts.speak(prefix, 1, null, "vr_prefix_" + System.currentTimeMillis());
            try { Thread.sleep(prefix.length() * 100L + 300L); } catch (Exception e) {}
        }
    }

    jdyPlayJayNativeVoice(amrPath);
    try { Thread.sleep(voiceDuration + 200L); } catch (Exception e) {}

    synchronized (messageQueue) {
        isSpeaking = false;
        if (!messageQueue.isEmpty()) {
            String next = (String) messageQueue.remove(0);
            speedText(next);
        }
    }
}

void jdyPlayVoiceWithIsSpeakingLock(String amrPath, long voiceDuration) {
    jdyPlayJayNativeVoice(amrPath);
    try { Thread.sleep(voiceDuration + 200L); } catch (Exception e) {}
    synchronized (messageQueue) {
        isSpeaking = false;
        if (!messageQueue.isEmpty()) {
            String next = (String) messageQueue.remove(0);
            speedText(next);
        }
    }
}

int jdyVoiceRelayMinOfDay() {
    java.util.Calendar cal = java.util.Calendar.getInstance();
    return cal.get(java.util.Calendar.HOUR_OF_DAY) * 60 + cal.get(java.util.Calendar.MINUTE);
}

int jdyVoiceRelayParseTime(String text) {
    try {
        if (text == null) return -1;
        String[] parts = text.trim().split(":");
        if (parts.length != 2) return -1;
        int h = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        return h * 60 + m;
    } catch (Exception e) { return -1; }
}

