LinearLayout jdyBuildSwitchRow(Activity act, String title, String desc, String key, boolean defValue) {
    LinearLayout row = new LinearLayout(act);
    row.setOrientation(LinearLayout.HORIZONTAL);
    row.setGravity(Gravity.CENTER_VERTICAL);
    row.setPadding(dp(18), dp(8), dp(18), dp(8));
    row.setMinimumHeight(dp(56));

    LinearLayout textBox = new LinearLayout(act);
    textBox.setOrientation(LinearLayout.VERTICAL);
    TextView titleView = T(act, title, 16, c("FF" + thText()), false);
    textBox.addView(titleView);
    if (desc != null && desc.length() > 0) {
        TextView descView = T(act, desc, 12, c("FF" + thText2()), false);
        descView.setPadding(0, dp(2), 0, 0);
        textBox.addView(descView);
    }
    row.addView(textBox, new LinearLayout.LayoutParams(0, -2, 1));

    Switch sw = new Switch(act);
    sw.setChecked(getBoolean(key, defValue));
    sw.setOnCheckedChangeListener(new CompoundButton.OnCheckedChangeListener() {
        public void onCheckedChanged(CompoundButton buttonView, boolean isChecked) {
            putBoolean(key, isChecked);
            if (key.equals(KEY_VOICE_RELAY)) jdyVoiceRelayEnabled = isChecked;
            else if (key.equals(KEY_VOICE_SPEAKER)) jdyVoiceRelaySpeakSender = isChecked;
            else if (key.equals(KEY_VOICE_QUIET)) jdyVoiceRelayQuietEnabled = isChecked;
        }
    });
    row.addView(sw);
    row.setOnClickListener(new View.OnClickListener() {
        public void onClick(View v) { sw.setChecked(!sw.isChecked()); }
    });
    return row;
}

