void showPeiyinVoiceList(android.content.Context c, final android.app.Dialog parentDlg) {
    final List voiceList = new ArrayList();
    final List voiceNames = new ArrayList();
    final int[] selectedIndex = {-1};

    android.widget.LinearLayout dlgLayout = new android.widget.LinearLayout(c);
    dlgLayout.setOrientation(1);
    dlgLayout.setGravity(android.view.Gravity.CENTER);
    dlgLayout.setPadding(dp(18), dp(12), dp(18), dp(12));

    android.widget.TextView tvTitle = T(c, "魔方 - 音色选择", 16, c("FF" + thAccent()), true);
    tvTitle.setGravity(android.view.Gravity.CENTER);
    tvTitle.setPadding(0, 0, 0, dp(8));
    dlgLayout.addView(tvTitle);

    android.widget.TextView tvLoading = T(c, "正在加载音色列表...", 12, c("FF" + thText2()), false);
    tvLoading.setGravity(android.view.Gravity.CENTER);
    tvLoading.setPadding(0, dp(28), 0, dp(28));
    dlgLayout.addView(tvLoading);

    android.widget.ListView listView = new android.widget.ListView(c);
    listView.setVisibility(android.view.View.GONE);
    android.widget.LinearLayout.LayoutParams lvParams = new android.widget.LinearLayout.LayoutParams(-1, 0, 1);
    listView.setLayoutParams(lvParams);
    listView.setDivider(new android.graphics.drawable.ColorDrawable(c("FF" + thBorder())));
    listView.setDividerHeight(dp(1));
    dlgLayout.addView(listView);

    android.widget.LinearLayout btnRow = new android.widget.LinearLayout(c);
    btnRow.setOrientation(0);
    btnRow.setGravity(android.view.Gravity.CENTER);
    btnRow.setPadding(0, dp(10), 0, 0);

    android.widget.Button btnConfirm = new android.widget.Button(c);
    btnConfirm.setText("确认");
    btnConfirm.setTextSize(13);
    btnConfirm.setAllCaps(false);
    btnConfirm.setBackgroundDrawable(createPrimaryBtnBg(8));
    btnConfirm.setTextColor(c("FF" + thText()));
    btnConfirm.setPadding(dp(22), dp(6), dp(22), dp(6));
    android.widget.LinearLayout.LayoutParams lpConfirm = new android.widget.LinearLayout.LayoutParams(-2, -2);
    lpConfirm.rightMargin = dp(12);
    btnConfirm.setLayoutParams(lpConfirm);
    btnRow.addView(btnConfirm);

    android.widget.Button btnCancel = new android.widget.Button(c);
    btnCancel.setText("取消");
    btnCancel.setTextSize(13);
    btnCancel.setAllCaps(false);
    btnCancel.setBackgroundDrawable(createDangerBtnBg(8));
    btnCancel.setTextColor(c("FF" + thText()));
    btnCancel.setPadding(dp(22), dp(6), dp(22), dp(6));
    btnRow.addView(btnCancel);

    dlgLayout.addView(btnRow);

    int dialogHDp = (int)(c.getResources().getDisplayMetrics().heightPixels * 0.7 / c.getResources().getDisplayMetrics().density);
    android.app.Dialog dlg = new android.app.Dialog(c);
    dlg.setCancelable(true);
    dlg.setCanceledOnTouchOutside(true);
    dlg.setContentView(dlgLayout);
    Window w = dlg.getWindow();
    if (w != null) {
        GradientDrawable gd = new GradientDrawable();
        gd.setOrientation(GradientDrawable.Orientation.TL_BR);
        gd.setColors(candyColors());
        gd.setCornerRadius(dp(16));
        gd.setStroke(dp(1), c("FF" + thBorder()));
        w.setBackgroundDrawable(gd);
        w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
        WindowManager.LayoutParams lp = w.getAttributes();
        lp.width = (int)(c.getResources().getDisplayMetrics().widthPixels * 0.85);
        lp.height = dp(dialogHDp);
        w.setAttributes(lp);
    }
    dlg.show();

    final android.widget.BaseAdapter adapter = new android.widget.BaseAdapter() {
        public int getCount() { return voiceNames.size(); }
        public Object getItem(int pos) { return null; }
        public long getItemId(int pos) { return pos; }
        public android.view.View getView(int pos, android.view.View v, android.view.ViewGroup p) {
            android.widget.LinearLayout row = new android.widget.LinearLayout(c);
            row.setOrientation(0);
            row.setGravity(android.view.Gravity.CENTER_VERTICAL);
            row.setPadding(dp(12), dp(8), dp(12), dp(8));

            android.widget.RadioButton rb = new android.widget.RadioButton(c);
            rb.setClickable(false);
            rb.setFocusable(false);
            rb.setChecked(pos == selectedIndex[0]);
            if (pos == selectedIndex[0]) {
                row.setBackgroundColor(c(isDarkMode() ? "30" + thAccent() : "FF" + thAccent2()));
            }
            row.addView(rb);

            android.widget.TextView tv = new android.widget.TextView(c);
            tv.setText((String) voiceNames.get(pos));
            tv.setTextSize(12);
            tv.setTextColor(c("FF" + thText()));
            tv.setPadding(dp(10), 0, 0, 0);
            row.addView(tv);

            return row;
        }
    };
    listView.setAdapter(adapter);

    listView.setOnItemClickListener(new android.widget.AdapterView.OnItemClickListener() {
        public void onItemClick(android.widget.AdapterView parent, android.view.View v, int pos, long id) {
            selectedIndex[0] = pos;
            adapter.notifyDataSetChanged();
        }
    });

    exec(new Runnable() {
        public void run() {
            try {
                java.net.URL u = new java.net.URL("https://peiyinmofang.com/api/open/v1/voices");
                java.net.HttpURLConnection conn = (java.net.HttpURLConnection) u.openConnection();
                conn.setRequestMethod("GET");
                conn.setConnectTimeout(10000);
                conn.setReadTimeout(15000);
        conn.setRequestProperty("Authorization", "Bearer " + peiyinApiKey);
                int httpCode = conn.getResponseCode();
                if (httpCode == 200) {
                    java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
                    StringBuilder sb = new StringBuilder();
                    String line;
                    while ((line = br.readLine()) != null) sb.append(line);
                    br.close();
                    String resp = sb.toString();
                    log(":" + resp);
                    JSONObject respJson = new JSONObject(resp);
                    JSONArray groups = respJson.getJSONArray("data");
                    List list = new ArrayList();
                    for (int i = 0; i < groups.length(); i++) {
                        JSONObject group = groups.getJSONObject(i);
                        JSONArray chars = group.getJSONArray("characters");
                        for (int j = 0; j < chars.length(); j++) list.add(chars.getJSONObject(j));
                    }
                    peiyinVoiceCache.put("__self__", list);
                    peiyinVoiceCacheTime.put("__self__", System.currentTimeMillis());
                    for (int i = 0; i < list.size(); i++) {
                        JSONObject vo = (JSONObject) list.get(i);
                        String name = vo.optString("name", "");
                        voiceList.add(vo.optString("voice_id", ""));
                        voiceNames.add(name);
                    }
                } else {
                    log("HTTP:" + httpCode);
                }
                conn.disconnect();
            } catch (Exception e) {
                log(":" + e.getMessage());
            }
            mainHandler.post(new Runnable() {
                public void run() {
                    tvLoading.setVisibility(android.view.View.GONE);
                    if (voiceNames.isEmpty()) {
                        tvLoading.setText("未配置配音API密钥");
                        tvLoading.setVisibility(android.view.View.VISIBLE);
                        return;
                    }
                    listView.setVisibility(android.view.View.VISIBLE);
                    for (int i = 0; i < voiceList.size(); i++) {
                        if (peiyinVoiceId.equals(voiceList.get(i))) {
                            selectedIndex[0] = i;
                            break;
                        }
                    }
                    adapter.notifyDataSetChanged();
                }
            });
        }
    });

    btnConfirm.setOnClickListener(new android.view.View.OnClickListener() {
        public void onClick(android.view.View v) {
            if (selectedIndex[0] >= 0 && selectedIndex[0] < voiceList.size()) {
                peiyinVoiceId = (String) voiceList.get(selectedIndex[0]);
                peiyinVoiceName = (String) voiceNames.get(selectedIndex[0]);
                saveEngineConfig();
                toast("" + peiyinVoiceName);
            }
            safeDismiss(dlg);
        }
    });

    btnCancel.setOnClickListener(new android.view.View.OnClickListener() {
        public void onClick(android.view.View v) {
            safeDismiss(dlg);
        }
    });
}

