boolean isUserInChatroom(String gid, String wxid) {
    try { getFriendDisplayName(wxid, gid); return true; } catch (Exception e) {}
    try { java.util.List m = getGroupMemberList(gid); return m != null && m.contains(wxid); } catch (Exception e) {}
    return false;
}

void showGroupForInvite(Context ctx) {
    if (manualInviteFriends.isEmpty()) {
        final List tmpGroups = new ArrayList();
        showSelectDialog(ctx, "选择目标群", true, new HashSet(), tmpGroups, new Runnable() {
            public void run() {
                manualInviteGroups.clear(); manualInviteGroups.addAll(tmpGroups);
                saveManualInviteGroups();
            }
        }, null, null, "发起邀请");
        return;
    }
    toast("正在检测 " + manualInviteFriends.size() + " 位好友的群成员...");
    exec(new Runnable() { public void run() {
        final java.util.Set eligible = new java.util.HashSet();
        final java.util.Set inGroups = new java.util.HashSet();
        try {
            java.util.List gl = getGroupList();
            if (gl != null) {
                for (int gi = 0; gi < gl.size(); gi++) {
                    String gid = resolveObjWxid(gl.get(gi)); if (gid == null) continue;
                    try { if (getGroupMemberCount(gid) >= manualInviteMaxMembers) continue; } catch (Exception e) { continue; }
                    boolean hasNonMember = false;
                    for (int fi = 0; fi < manualInviteFriends.size(); fi++) {
                        if (!isUserInChatroom(gid, (String) manualInviteFriends.get(fi))) { hasNonMember = true; break; }
                    }
                    if (hasNonMember) eligible.add(gl.get(gi)); else inGroups.add(gid);
                }
            }
        } catch (Exception e) {}
        final int ec = eligible.size();
        log("扫描: " + (eligible.size() + inGroups.size()) + "群 " + ec + "不在 + " + inGroups.size() + "已在");
        mainHandler.post(new Runnable() { public void run() {
            if (ec == 0) { toast("所有好友已在全群中"); return; }
            final List tmpGroups = new ArrayList(eligible);
            showSelectDialog(ctx, "好友不在的" + ec + "个群", true, new HashSet(), tmpGroups, new Runnable() {
                public void run() {
                    manualInviteGroups.clear(); manualInviteGroups.addAll(tmpGroups);
                    saveManualInviteGroups();
                }
            }, null, new ArrayList(eligible), "发起邀请");
        }});
    }});
}

