    btnSearch.setBackgroundDrawable(createPrimaryBtnBg(6));
    btnSearch.setTextColor(c("FF" + thText()));
    btnSearch.setPadding(dp(16), dp(6), dp(16), dp(6));
    ctrlRow.addView(btnSearch);
    root.addView(ctrlRow);
    root.addView(SP(c, dp(6)));

    final android.widget.ScrollView sv = new android.widget.ScrollView(c);
    sv.setBackgroundDrawable(createCardBg(6));
    sv.setPadding(dp(6), dp(6), dp(6), dp(6));
    android.widget.LinearLayout.LayoutParams svLp = new android.widget.LinearLayout.LayoutParams(-1, 0, 1);
    sv.setLayoutParams(svLp);
    final android.widget.LinearLayout results = new android.widget.LinearLayout(c);
    results.setOrientation(1);
    sv.addView(results);
    root.addView(sv);
