    final android.widget.LinearLayout downloadBar = new android.widget.LinearLayout(c);
    downloadBar.setOrientation(1);
    downloadBar.setPadding(dp(8), dp(4), dp(8), dp(4));
    downloadBar.setVisibility(android.view.View.GONE);
