    tvDownloadName.setPadding(0, 0, 0, dp(2));
    downloadBar.addView(tvDownloadName);
    final android.widget.ProgressBar pbDownloadGlobal = new android.widget.ProgressBar(c, null, android.R.attr.progressBarStyleHorizontal);
    pbDownloadGlobal.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1, dp(12)));
    pbDownloadGlobal.setMax(100);
    downloadBar.addView(pbDownloadGlobal);
    root.addView(downloadBar);

    final android.widget.LinearLayout bottomRow = new android.widget.LinearLayout(c);
    bottomRow.setOrientation(0);
    bottomRow.setGravity(android.view.Gravity.CENTER);
    bottomRow.setLayoutParams(new android.widget.LinearLayout.LayoutParams(-1, -2));

    final android.widget.TextView tvPage = T(c, "", 11, c("FF" + thText2()), false);
    tvPage.setPadding(0, 0, dp(8), 0);
