                    sv.setEnabled(false);
                    ((android.widget.Button) sv).setText("...");
                    if (downloadBarDyyy != null) downloadBarDyyy.setVisibility(android.view.View.VISIBLE);
                    if (tvDownloadNameDyyy != null) tvDownloadNameDyyy.setText("发送: " + displayNameFinal);
                    if (pbDownloadGlobalDyyy != null) pbDownloadGlobalDyyy.setProgress(0);
