void showDyyyPage(Context c, String[] titles, String[] urls, int page, int pageSize,
                  android.widget.LinearLayout results, android.widget.TextView tvPage,
                  android.widget.Button btnPrev, android.widget.Button btnNext,
                  android.widget.LinearLayout downloadBarDyyy, android.widget.TextView tvDownloadNameDyyy, android.widget.ProgressBar pbDownloadGlobalDyyy) {
    results.removeAllViews();
    int totalPages = (titles.length + pageSize - 1) / pageSize;
    int start = page * pageSize;
    int end = Math.min(start + pageSize, titles.length);
    for (int i = start; i < end; i++) {
        final String l = titles[i].trim();
        if (l.isEmpty()) continue;
        addDyyyItem(c, l, i + 1, urls[i], results, downloadBarDyyy, tvDownloadNameDyyy, pbDownloadGlobalDyyy);
    }
    tvPage.setText("第 " + (page + 1) + "/" + totalPages + " 页");
    btnPrev.setVisibility(page > 0 ? android.view.View.VISIBLE : android.view.View.GONE);
    btnNext.setVisibility(page < totalPages - 1 ? android.view.View.VISIBLE : android.view.View.GONE);
}

