void resolveLink(final Context c, final String link, final android.widget.LinearLayout results, final android.widget.TextView tvStatus, final android.widget.Button btnParse,
                    final android.widget.LinearLayout downloadBarLg, final android.widget.TextView tvDownloadNameLg, final android.widget.ProgressBar pbDownloadGlobalLg) {
    java.net.HttpURLConnection conn = null;
    String finalLink = link;
    try {
        if (finalLink.contains("m.kugou.com/share/song.html") || finalLink.contains("www.kugou.com/share/")) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("解析分享链接..."); } });
            conn = (java.net.HttpURLConnection) new java.net.URL(finalLink).openConnection();
            conn.setConnectTimeout(10000); conn.setReadTimeout(10000); conn.setInstanceFollowRedirects(true);
            java.io.BufferedReader br2 = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
            StringBuilder html = new StringBuilder(); String l;
            while ((l = br2.readLine()) != null) html.append(l);
            br2.close(); conn.disconnect(); conn = null;
            String htmlStr = html.toString();
            int hashIdx = htmlStr.indexOf("\"hash\":\"");
            if (hashIdx < 0) {
                int dsIdx = htmlStr.indexOf("dataFromSmarty");
                if (dsIdx > 0) hashIdx = htmlStr.indexOf("\"hash\":\"", dsIdx);
            }
            if (hashIdx > 0) {
                int hs = hashIdx + 8;
                int he = htmlStr.indexOf("\"", hs);
                if (he > hs) {
                    String kgHash = htmlStr.substring(hs, he);
                    finalLink = "https://www.kugou.com/song/#hash=" + kgHash;
                    log("kw: resolved kugou hash=" + kgHash + " url=" + finalLink);
                }
            }
        }
        String api = "https://apis.kit9.cn/api/aggregate_music/api.php?link=" + java.net.URLEncoder.encode(finalLink, "UTF-8");
        log("kw: parse api=" + api);
        if (conn != null) { try { conn.disconnect(); } catch (Exception ignored) {} }
        conn = (java.net.HttpURLConnection) new java.net.URL(api).openConnection();
        conn.setConnectTimeout(15000); conn.setReadTimeout(15000);
        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder(); String line;
        while ((line = br.readLine()) != null) sb.append(line);
        br.close(); conn.disconnect(); conn = null;
        final String resp = sb.toString();
        log("kw: resp=" + resp);
        org.json.JSONObject json = new org.json.JSONObject(resp);
        int code = json.optInt("code", -1);
        if (code == 403) {
            final String err = json.optString("error", "需要付费");
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("付费歌曲: " + err); btnParse.setEnabled(true); } });
            return;
        }
        if (code != 200) {
            final String msg = json.optString("msg", "请求失败");
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText(msg); btnParse.setEnabled(true); } });
            return;
        }
        org.json.JSONObject data = json.optJSONObject("data");
        if (data == null) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("无数据"); btnParse.setEnabled(true); } });
            return;
        }
        final String songName = data.optString("music_songname", "");
        final String artist = data.optString("music_author", "");
        final String cover = data.optString("music_cover", "");
        final String lrc = data.optString("music_lrc", "");
        final String musicUrl = data.optString("music_link", "");
        final String parseType = json.optString("parsing_type", "");
        if (songName.isEmpty() && musicUrl.isEmpty()) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("解析失败"); btnParse.setEnabled(true); } });
            return;
        }
        mainHandler.post(new Runnable() {
            public void run() {
                tvStatus.setText("解析: " + parseType);
                btnParse.setEnabled(true);
                addLgItem(c, 0, songName, artist, lrc, musicUrl, cover,
                    results, downloadBarLg, tvDownloadNameLg, pbDownloadGlobalLg, null, null, "kugou");
            }
        });
    } catch (Exception e) {
        final String errMsg = e.getMessage();
        log("kw: parse error: " + (errMsg != null ? errMsg : "nil"));
        if (conn != null) { try { conn.disconnect(); } catch (Exception ignored) {} }
        mainHandler.post(new Runnable() { public void run() { tvStatus.setText("解析失败: " + (errMsg != null ? errMsg : "网络错误")); btnParse.setEnabled(true); } });
    }
}

void searchKugou(final Context c, final String keyword, final int page, final android.widget.LinearLayout results, final android.widget.TextView tvStatus, final android.widget.Button btnParse,
                 final android.widget.LinearLayout downloadBarLg, final android.widget.TextView tvDownloadNameLg, final android.widget.ProgressBar pbDownloadGlobalLg,
                 final android.widget.Button btnPrev, final android.widget.Button btnNext, final android.widget.TextView tvPage) {
    java.net.HttpURLConnection conn = null;
    try {
        String api = "https://songsearch.kugou.com/song_search_v2?keyword=" + java.net.URLEncoder.encode(keyword, "UTF-8")
            + "&page=" + page + "&pagesize=20&platform=WebFilter&userid=0&clientver=&filter=2&iscorrection=1&privilege_filter=0";
        log("kw: search api=" + api);
        conn = (java.net.HttpURLConnection) new java.net.URL(api).openConnection();
        conn.setConnectTimeout(10000); conn.setReadTimeout(10000);
        conn.setRequestProperty("User-Agent", "Mozilla/5.0");
        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder(); String line;
        while ((line = br.readLine()) != null) sb.append(line);
        br.close(); conn.disconnect(); conn = null;
        String resp = sb.toString();
        log("kw: search resp len=" + resp.length());
        org.json.JSONObject json = new org.json.JSONObject(resp);
        if (json.optInt("status") != 1) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("搜索失败"); btnParse.setEnabled(true); if (btnPrev != null) btnPrev.setVisibility(android.view.View.GONE); if (btnNext != null) btnNext.setVisibility(android.view.View.GONE); } });
            return;
        }
        org.json.JSONArray list = json.optJSONObject("data").optJSONArray("lists");
        if (list == null || list.length() == 0) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("未找到歌曲"); btnParse.setEnabled(true); if (btnPrev != null) btnPrev.setVisibility(android.view.View.GONE); if (btnNext != null) btnNext.setVisibility(android.view.View.GONE); } });
            return;
        }
        final int total = json.optJSONObject("data").optInt("total", 0);
        final int count = list.length();
        mainHandler.post(new Runnable() {
            public void run() {
                int maxPage = (int) Math.ceil(total / 20.0);
                String pageStr = page + "/" + Math.max(maxPage, 1);
                tvStatus.setText(pageStr + " (共" + total + "首)");
                if (tvPage != null) tvPage.setText(pageStr + " 页");
                btnParse.setEnabled(true);
                if (btnPrev != null) {
                    if (page > 1) { btnPrev.setVisibility(android.view.View.VISIBLE); btnPrev.setEnabled(true); } else { btnPrev.setVisibility(android.view.View.GONE); }
                }
                if (btnNext != null) {
                    int maxPage = (int) Math.ceil(total / 20.0);
                    if (page < maxPage) { btnNext.setVisibility(android.view.View.VISIBLE); btnNext.setEnabled(true); } else { btnNext.setVisibility(android.view.View.GONE); }
                }
                results.removeAllViews();
                for (int i = 0; i < count; i++) {
                    org.json.JSONObject item = list.optJSONObject(i);
                    if (item == null) continue;
                    String songName = item.optString("SongName", "");
                    String artist = item.optString("SingerName", "");
                    String album = item.optString("AlbumName", "");
                    String kgHash = item.optString("HQFileHash", item.optString("SQFileHash", item.optString("FileHash", "")));
                        String cover = item.optString("img", item.optString("Image", item.optString("AlbumImage", item.optString("cover", ""))));
                        if (!cover.isEmpty()) cover = cover.replace("{size}", "240");
                        if ((cover.isEmpty() || !cover.startsWith("http")) && item.has("AlbumID")) {
                            String aid = item.optString("AlbumID", "");
                            if (!aid.isEmpty()) cover = "https://imge.kugou.com/stdmusic/240/" + aid + ".png";
                        }
                        if (!cover.isEmpty() && !cover.startsWith("http")) cover = "";
                        if (!songName.isEmpty() && !kgHash.isEmpty()) {
                            addLgItem(c, i + 1, songName, artist, "", null, cover,
                                results, downloadBarLg, tvDownloadNameLg, pbDownloadGlobalLg, null, kgHash, "kugou");
                    }
                }
            }
        });
    } catch (Exception e) {
        final String errMsg = e.getMessage();
        log("kw: search error: " + (errMsg != null ? errMsg : "nil"));
        if (conn != null) { try { conn.disconnect(); } catch (Exception ignored) {} }
        mainHandler.post(new Runnable() { public void run() { tvStatus.setText("搜索失败: " + (errMsg != null ? errMsg : "网络错误")); btnParse.setEnabled(true); if (btnPrev != null) btnPrev.setVisibility(android.view.View.GONE); if (btnNext != null) btnNext.setVisibility(android.view.View.GONE); } });
    }
}

void handleDianGe(String talker, String keyword) {
    // 1. Search Kugou
    String searchApi = null;
    java.net.HttpURLConnection sconn = null;
    try {
        searchApi = "https://songsearch.kugou.com/song_search_v2?keyword=" + java.net.URLEncoder.encode(keyword, "UTF-8")
            + "&page=1&pagesize=1&platform=WebFilter&userid=0&clientver=&filter=2&iscorrection=1&privilege_filter=0";
        log("dg: search " + keyword);
        sconn = (java.net.HttpURLConnection) new java.net.URL(searchApi).openConnection();
        sconn.setConnectTimeout(8000); sconn.setReadTimeout(8000);
        sconn.setRequestProperty("User-Agent", "Mozilla/5.0");
        java.io.BufferedReader sbr = new java.io.BufferedReader(new java.io.InputStreamReader(sconn.getInputStream(), "UTF-8"));
        StringBuilder ssb = new StringBuilder(); String sl;
        while ((sl = sbr.readLine()) != null) ssb.append(sl);
        sbr.close(); sconn.disconnect(); sconn = null;
        org.json.JSONObject j = new org.json.JSONObject(ssb.toString());
        if (j.optInt("status") != 1) { log("dg: search failed"); sendText(talker, "[点歌] 未搜索到歌曲: " + keyword); return; }
        org.json.JSONArray list = j.optJSONObject("data").optJSONArray("lists");
        if (list == null || list.length() == 0) { log("dg: no result"); sendText(talker, "[点歌] 未找到歌曲: " + keyword); return; }
        org.json.JSONObject item = list.optJSONObject(0);
        String songName = item.optString("SongName", "");
        String artist = item.optString("SingerName", "");
        String kgHash = item.optString("HQFileHash", item.optString("SQFileHash", item.optString("FileHash", "")));
        if (kgHash.isEmpty()) { log("dg: no hash"); sendText(talker, "[点歌] 获取歌曲链接失败"); return; }
        log("dg: found " + songName + " - " + artist + " hash=" + kgHash);

        // 2. Get play URL via music.haitangw.cc (exhigh for speed)
        java.net.HttpURLConnection pconn = (java.net.HttpURLConnection) new java.net.URL("https://music.haitangw.cc/kgqq1/kg.php?id=" + kgHash + "&type=json&level=exhigh").openConnection();
        pconn.setConnectTimeout(5000); pconn.setReadTimeout(5000);
        java.io.BufferedReader pbr = new java.io.BufferedReader(new java.io.InputStreamReader(pconn.getInputStream(), "UTF-8"));
        StringBuilder psb = new StringBuilder(); String pl;
        while ((pl = pbr.readLine()) != null) psb.append(pl);
        pbr.close(); pconn.disconnect();
        org.json.JSONObject pj = new org.json.JSONObject(psb.toString());
        if (pj.optInt("code") != 200) { log("dg: kgphp failed code=" + pj.optInt("code")); sendText(talker, "[点歌] 获取播放链接失败"); return; }
        String playUrl = pj.optJSONObject("data").optString("url", "");
        if (playUrl.isEmpty()) { log("dg: kgphp empty url"); sendText(talker, "[点歌] 获取播放链接失败"); return; }
        log("dg: got play url");

        // 3. Download MP3
        String safeName = (songName + " - " + artist).replaceAll("[/\\\\:*?\"<>|]", "_");
        String dgDir = cacheDir + "/diange";
        new java.io.File(dgDir).mkdirs();
        String mp3Path = dgDir + "/" + safeName + "_" + System.currentTimeMillis() + ".mp3";
        java.net.HttpURLConnection dconn = (java.net.HttpURLConnection) new java.net.URL(playUrl).openConnection();
        dconn.setConnectTimeout(15000); dconn.setReadTimeout(15000);
        dconn.setInstanceFollowRedirects(true);
        dconn.setRequestProperty("User-Agent", "Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X)");
        java.io.InputStream is = dconn.getInputStream();
        java.io.FileOutputStream fos = new java.io.FileOutputStream(mp3Path);
        byte[] buf = new byte[8192]; int len;
        while ((len = is.read(buf)) > 0) fos.write(buf, 0, len);
        fos.close(); is.close(); dconn.disconnect();
        log("dg: downloaded " + new java.io.File(mp3Path).length() + " bytes");

        // 4. Convert to silk
        String silkPath = dgDir + "/dg_" + System.currentTimeMillis() + ".silk";
        mp3ToSilk(mp3Path, silkPath);
        log("dg: converted to silk");

        // 5. Send voice
        sendVoice(talker, silkPath);
        log("dg: sent voice to " + talker);

        // 6. Delete temp files
        try { new java.io.File(mp3Path).delete(); } catch (Exception ignored) {}
        try { new java.io.File(silkPath).delete(); } catch (Exception ignored) {}
        log("dg: cleaned up temp files");
    } catch (Exception e) {
        log("dg: error " + (e.getMessage() != null ? e.getMessage() : ""));
        try { sendText(talker, "[点歌] 点歌失败，请稍后重试"); } catch (Exception ignored) {}
    } finally {
        if (sconn != null) try { sconn.disconnect(); } catch (Exception ignored) {}
    }
}

