void handleDouyinProfileAuto(final String talker, String linkUrl) {
    if (douyinProfileCkey.isEmpty()) return;
    log("dyAuto: fetching profile for " + linkUrl);
    exec(new Runnable() {
        public void run() {
            java.net.HttpURLConnection conn = null;
            java.io.InputStream is = null;
            java.io.BufferedReader br = null;
            try {
                String api = "https://api.317ak.com/api/spjx/dyzyjx?ckey=" + java.net.URLEncoder.encode(douyinProfileCkey, "UTF-8") +
                             "&url=" + java.net.URLEncoder.encode(linkUrl, "UTF-8") + "&count=50";
                java.net.URL apiUrl = new java.net.URL(api);
                conn = (java.net.HttpURLConnection) apiUrl.openConnection();
                conn.setRequestMethod("GET");
                conn.setConnectTimeout(15000);
                conn.setReadTimeout(15000);
                conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Linux; Android 12) AppleWebKit/537.36");
                int code = conn.getResponseCode();
                if (code >= 200 && code < 300) { is = conn.getInputStream(); } else { is = conn.getErrorStream(); }
                if (is == null) { log("dyAuto: http err " + code); return; }
                br = new java.io.BufferedReader(new java.io.InputStreamReader(is, "UTF-8"));
                StringBuilder sb = new StringBuilder(); String line;
                while ((line = br.readLine()) != null) sb.append(line);
                org.json.JSONObject jsonObj = new org.json.JSONObject(sb.toString());
                if (jsonObj.optInt("code", -1) != 200) { log("dyAuto: api err"); return; }
                org.json.JSONArray dataArr = jsonObj.optJSONArray("data");
                if (dataArr == null || dataArr.length() == 0) { log("dyAuto: no videos"); return; }
                int total = dataArr.length();
                log("dyAuto: parsed " + total + " videos");
                int success = 0;
                for (int i = 0; i < total; i++) {
                    org.json.JSONObject video = dataArr.optJSONObject(i);
                    String vUrl = video.optString("url", "");
                    String vDesc = video.optString("desc", "视频" + (i + 1));
                    if (vUrl.isEmpty()) continue;
                    String filePath = downloadVideoFileSync(vUrl, vDesc);
                    if (filePath != null) {
                        sendVideo(talker, filePath);
                        success++;
                    }
                    try { Thread.sleep(2000); } catch (Exception ignored) {}
                }
                log("dyAuto: sent " + success + "/" + total + " videos");
            } catch (Exception e) {
                log("dyAuto: exception " + e.getMessage());
            } finally {
                try { if (br != null) br.close(); } catch (Exception ignored) {}
                try { if (is != null) is.close(); } catch (Exception ignored) {}
                if (conn != null) conn.disconnect();
            }
        }
    });
}

void handleDouyinLink(final String talker, String linkUrl) {
    final String apiUrl = "https://cf.eval.qzz.io/?data&url=" + linkUrl;
    get(apiUrl, null, respContent -> {
        try {
            org.json.JSONObject jsonObj = new org.json.JSONObject((String) respContent);
            String type = jsonObj.optString("type");
            String id = jsonObj.optString("aweme_id");
            if ("video".equals(type)) {
                final String videoUrl = jsonObj.optString("video_url");
                download(videoUrl, cacheDir + "/dyVideo" + id + ".mp4", null, file -> {
                    sendVideo(talker, ((java.io.File) file).getAbsolutePath());
                });
            } else if ("img".equals(type)) {
                final org.json.JSONArray imageUrlList = jsonObj.optJSONArray("image_url_list");
                if (imageUrlList != null) {
                    for (int i = 0; i < imageUrlList.length(); i++) {
                        final String imgUrl = imageUrlList.optString(i);
                        final int idx = i;
                        download(imgUrl, cacheDir + "/dyImg" + idx + ".jpg", null, file -> {
                            sendImage(talker, ((java.io.File) file).getAbsolutePath());
                            saveToMediaDir((java.io.File) file);
                        });
                    }
                }
            } else {
                sendText(talker, "[]:" + type);
            }
        } catch (Exception e) {
            sendText(talker, "[]:" + e.getMessage());
        }
    });
}
