void onMemberChange(String type, String groupWxid, String userWxid, String userName) {
    if (type.equals("join") && blacklistEnabled && blacklistMap.containsKey(userWxid)) {
        try { delChatroomMember(groupWxid, userWxid); } catch (Exception e) { log("黑名单移出失败: " + e.getMessage()); }
        log("黑名单成员尝试进群已自动移出: " + userWxid + " @ " + groupWxid);
        return;
    }
    if (welcomeEnabled && type.equals("join")) {
        sendWelcomeNotice(groupWxid, userWxid);
    }
    if (activityStatsEnabled && type.equals("left")) {
        log("成员退出: " + userName + " from " + groupWxid);
    }
    if (leftGroupTipEnabled && type.equals("left")) {
        String msg = leftGroupTipMsg.replace("{userName}", userName);
        sendText(groupWxid, msg);
    }
    if (blacklistEnabled && type.equals("left")) {
        addToBlacklist(userWxid, groupWxid, "被移出/退出群聊");
    }
}

void onNewFriend(String wxid, String ticket, int scene) {
    log("新好友申请: " + wxid + " scene=" + scene);
    if (autoAcceptFriend) {
        try {
            verifyUser(wxid, ticket, scene);
            log("已自动通过好友: " + wxid);
            final String fWxid = wxid;
            delay(2000, new Runnable() { public void run() {
                sendText(fWxid, autoAcceptFriendMsg);
                log("已发送欢迎消息: " + fWxid);
            }});
        } catch (Exception e) {
            log("自动通过好友失败: " + e.getMessage());
        }
    }
}

void handleGroupInvite(String talker) {
    try {
        if (groupInviteTargets.isEmpty()) {
            sendText(talker, "暂无可邀请的群组");
            return;
        }
        String suitableGroup = getSuitableGroupForInvite();
        if (suitableGroup != null && !suitableGroup.isEmpty()) {
            inviteChatroomMember(suitableGroup, talker);
            sendText(talker, "群聊邀请已发送，请查收");
            log("已邀请 " + talker + " 进入群 " + suitableGroup);
        } else {
            sendText(talker, "所有群组都已满员，请稍后重试");
        }
    } catch (Exception e) {
        log("群邀请失败: " + e.getMessage());
        sendText(talker, "邀请发送失败，请稍后重试");
    }
}

