void executeManualInvite() {
    try {
        int totalSuccess = 0; int totalFail = 0;
        for (int j = 0; j < manualInviteGroups.size(); j++) {
            String gid = (String) manualInviteGroups.get(j);
            String gn = getGroupName(gid); if (gn == null || gn.isEmpty()) gn = gid;
            try { if (getGroupMemberCount(gid) >= manualInviteMaxMembers) { log("跳过 " + gn + " (已满)"); continue; } } catch (Exception e) { continue; }
            java.util.List toInvite = new java.util.ArrayList();
            try {
                java.util.List members = getGroupMemberList(gid);
                for (int i = 0; i < manualInviteFriends.size(); i++) {
                    String wid = (String) manualInviteFriends.get(i);
                    if (members == null || !members.contains(wid)) toInvite.add(wid);
                }
            } catch (Exception e) { toInvite.addAll(manualInviteFriends); }
            if (toInvite.isEmpty()) { log(gn + " 所有好友已在群内"); continue; }
            String names = "";
            for (int i = 0; i < toInvite.size(); i++) {
                String n = getFriendRemarkName((String) toInvite.get(i));
                if (n == null || n.isEmpty()) n = getFriendNickName((String) toInvite.get(i));
                if (n == null || n.isEmpty()) n = getFriendName((String) toInvite.get(i));
                if (n != null && !n.isEmpty()) names += (names.isEmpty() ? "" : ",") + n;
            }
            try {
                inviteChatroomMember(gid, toInvite);
                totalSuccess += toInvite.size();
                log(gn + " 邀请 " + toInvite.size() + " 人成功: " + names);
            } catch (Exception e) {
                String err = e != null && e.getMessage() != null ? e.getMessage() : "";
                if (err.contains("已在") || err.contains("exist") || err.contains("already") || err.contains("重复")) {
                    int s = 0;
                    for (int i = 0; i < toInvite.size(); i++) {
                        try {
                            inviteChatroomMember(gid, (String) toInvite.get(i));
                            s++;
                        } catch (Exception ee) {}
                        try { delay(1500, new Runnable() { public void run() {} }); } catch (Exception ee) {}
                    }
                    totalSuccess += s; totalFail += toInvite.size() - s;
                } else {
                    totalFail += toInvite.size();
                    log(gn + " 邀请失败: " + err);
                }
            }
            try { delay(2000, new Runnable() { public void run() {} }); } catch (Exception ee) {}
        }
        final String msg = "邀请完毕: 成功" + totalSuccess + " 失败" + totalFail;
        log(msg);
        mainHandler.post(new Runnable() { public void run() { toast(msg); } });
    } catch (Exception e) {
        log("异常: " + e.getMessage());
        mainHandler.post(new Runnable() { public void run() { toast("邀请异常: " + e.getMessage()); } });
    }
}

