/**
 * 恢复所有定时任务
 */
void restoreAllTasks() {
    try {
        String tasksJson = getString(CONFIG_KEY, KEY_TASKS, "{}");
        JSONObject allTasks = parseJsonObjectSafe(tasksJson);

        if (allTasks == null || allTasks.length() == 0) return;

        long now = System.currentTimeMillis();
        int restoredCount = 0;

        Iterator keys = allTasks.keys();
        while (keys.hasNext()) {
            String taskId = String.valueOf(keys.next());
            JSONObject task = allTasks.optJSONObject(taskId);
            if (task == null) continue;
            String status = task.optString("status", "pending");
            int repeatType = task.optInt("repeatType", 0);
            boolean sendOnTimeout = task.optBoolean("sendOnTimeout", true);

            // 进程被杀后，running 状态可能遗留；启动时统一纠正，避免卡在“执行中”。
            if ("running".equals(status)) {
                if (repeatType > 0) {
                    task.put("status", "pending");
                } else {
                    task.put("status", "completed");
                    task.put("completedTime", task.optLong("completedTime", System.currentTimeMillis()));
                    continue;
                }
            }

            // 已完成/已过期任务不再恢复执行，防止重启后误恢复。
            if ("completed".equals(status) || "expired".equals(status)) {
                continue;
            }

            long planTime = task.optLong("planTime", 0);
            if (planTime <= 0) continue;

            scheduledTasks.put(taskId, task);

            if (now >= planTime) {
                long missMs = now - planTime;

                if (repeatType > 0) {
                    if (sendOnTimeout) {
                        // 循环任务：只要错过就补发一次，避免直接跳到下一轮导致“第二天不执行”的体感问题。
                        task.put("status", "pending");
                        log("检测到错过的循环任务" + taskId + "（晚点" + missMs + "ms），准备补发...");
                        notify("定时发送补发", "检测到循环任务" + taskId + "即将补发...");
                        scheduleTaskWithPrecision(taskId, task, 1000);
                        restoredCount++;
                    } else {
                        JSONArray repeatDaysArray = task.optJSONArray("repeatDays");
                        long nextPlanTime = calculateNextFuturePlanTime(planTime, repeatType, repeatDaysArray, now);
                        if (nextPlanTime > now) {
                            task.put("planTime", nextPlanTime);
                            task.put("status", "pending");
                            long nextDelay = nextPlanTime - now;
                            scheduleTaskWithPrecision(taskId, task, nextDelay);
                            restoredCount++;
                            log("循环任务" + taskId + "已跳过超时补发，顺延到" + formatTimeWithSeconds(nextPlanTime));
                        } else {
                            task.put("status", "expired");
                            log("循环任务" + taskId + "超时且无法顺延，已标记过期");
                        }
                    }
                } else if (sendOnTimeout && missMs < 10 * 60 * 1000) {
                    log("检测到错过的任务" + taskId + "（10分钟内），准备补发...");
                    notify("定时发送补发", "检测到任务" + taskId + "即将补发...");
                    scheduleTaskWithPrecision(taskId, task, 1000);
                    restoredCount++;
                } else {
                    task.put("status", "expired");
                    if (sendOnTimeout) {
                        log("任务" + taskId + "已过期");
                    } else {
                        log("任务" + taskId + "已超时，已按配置跳过发送");
                    }
                    continue;
                }
            } else {
                long delay = planTime - now;
                scheduleTaskWithPrecision(taskId, task, delay);
                restoredCount++;
            }
        }

        saveAllTasks();

        if (restoredCount > 0) {
            log("已恢复" + restoredCount + "个定时任务");
        }
    } catch (Exception e) {
        log("恢复任务失败:" + e.getMessage());
    }
}

long calculateNextFuturePlanTime(long currentPlanTime, int repeatType, JSONArray repeatDaysArray, long now) {
    long nextPlanTime = currentPlanTime;
    int guard = 0;
    while (nextPlanTime > 0 && nextPlanTime <= now && guard < 400) {
        nextPlanTime = calculateNextPlanTime(nextPlanTime, repeatType, repeatDaysArray);
        guard++;
    }
    return nextPlanTime;
}

/**
 * 【专为语音设计的同步锁】
 */
void runOnMainSync(final Runnable runnable) {
    if (Looper.myLooper() == Looper.getMainLooper()) {
        runnable.run();
        return;
    }
    final CountDownLatch latch = new CountDownLatch(1);
    new Handler(Looper.getMainLooper()).post(new Runnable() {
        public void run() {
            try {
                runnable.run();
            } catch (Exception e) {
                log("UI线程执行异常:" + e.getMessage());
            } finally {
                latch.countDown();
            }
        }
    });
    try {
        latch.await(15, TimeUnit.SECONDS);
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}

boolean performSendWithRetry(final String actionName, final boolean runOnMainThread, final SendAction action) {
    for (int attempt = 1; attempt <= SEND_MAX_RETRY; attempt++) {
        try {
            if (runOnMainThread) {
                final AtomicReference<Exception> errorRef = new AtomicReference<Exception>(null);
                runOnMainSync(new Runnable() {
                    public void run() {
                        try {
                            action.run();
                        } catch (Exception e) {
                            errorRef.set(e);
                        }
                    }
                });
                Exception err = errorRef.get();
                if (err != null) throw err;
            } else {
                action.run();
            }

            if (attempt > 1) {
                log(actionName + "重试成功: 第" + attempt + "次");
            }
            return true;
        } catch (Exception e) {
            log(actionName + "第" + attempt + "次失败:" + e.getMessage());
            if (attempt < SEND_MAX_RETRY) {
                try {
                    Thread.sleep(SEND_RETRY_BASE_MS * attempt);
                } catch (Exception ignored) {}
            }
        }
    }
    return false;
}

void warmupSendPipeline(boolean blocking, final String reason) {
    if (sendPipelineWarmed) return;
    Runnable warmJob = new Runnable() {
        public void run() {
            synchronized (sendWarmLock) {
                if (sendPipelineWarmed) return;
                long begin = System.currentTimeMillis();
                try {
                    if (sCachedFriendList == null) sCachedFriendList = getFriendList();
                    if (sCachedGroupList == null) sCachedGroupList = getGroupList();
                    sendPipelineWarmed = true;
                    long cost = System.currentTimeMillis() - begin;
                    log("发送链路预热完成(" + reason + "):" + cost + "ms");
                } catch (Exception e) {
                    long cost = System.currentTimeMillis() - begin;
                    log("发送链路预热失败(" + reason + "):" + cost + "ms," + e.getMessage());
                }
            }
        }
    };

    if (blocking) {
        warmJob.run();
    } else {
        exec(warmJob);
    }
}

void scheduleTaskPrewarm(final String taskId, long delayMillis) {
    Runnable old = (Runnable) taskPrewarmRunnables.get(taskId);
    if (old != null) {
        scheduleHandler.removeCallbacks(old);
        taskPrewarmRunnables.remove(taskId);
    }
    if (sendPipelineWarmed) return;
    if (delayMillis < 7000) return;

    long prewarmDelay = Math.max(0, delayMillis - 5000);
    Runnable prewarmRunnable = new Runnable() {
        public void run() {
            warmupSendPipeline(false, "task_prewarm:" + taskId);
            taskPrewarmRunnables.remove(taskId);
        }
    };
    taskPrewarmRunnables.put(taskId, prewarmRunnable);
    scheduleHandler.postDelayed(prewarmRunnable, prewarmDelay);
}

void acquireMassSendWakeLock(String reason) {
    synchronized (massSendWakeLockLock) {
        try {
            massSendWakeLockRefs++;
            if (massSendWakeLock != null && massSendWakeLock.isHeld()) return;
            Context ctx = getBestContext();
            if (ctx == null) return;
            PowerManager pm = (PowerManager) ctx.getSystemService(Context.POWER_SERVICE);
            if (pm == null) return;
            massSendWakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "wauxv:mass-send");
            massSendWakeLock.setReferenceCounted(false);
            massSendWakeLock.acquire(2 * 60 * 60 * 1000L);
            log("已申请群发后台保活 WakeLock:" + reason);
        } catch (Exception e) {
            log("群发 WakeLock 申请失败:" + e.getMessage());
        }
    }
}

void releaseMassSendWakeLock(String reason) {
    synchronized (massSendWakeLockLock) {
        try {
            if (massSendWakeLockRefs > 0) massSendWakeLockRefs--;
            if (massSendWakeLockRefs > 0) return;
            if (massSendWakeLock != null && massSendWakeLock.isHeld()) {
                massSendWakeLock.release();
                log("已释放群发后台保活 WakeLock:" + reason);
            }
        } catch (Exception ignored) {}
        massSendWakeLock = null;
        massSendWakeLockRefs = 0;
    }
}

void releaseAllMassSendWakeLocks(String reason) {
    synchronized (massSendWakeLockLock) {
        try {
            if (massSendWakeLock != null && massSendWakeLock.isHeld()) {
                massSendWakeLock.release();
                log("已强制释放群发后台保活 WakeLock:" + reason);
            }
        } catch (Exception ignored) {}
        massSendWakeLock = null;
        massSendWakeLockRefs = 0;
    }
}

/**
 * 高精度定时执行（精确到毫秒级，误差<100ms）
 */
void scheduleTaskWithPrecision(final String taskId, JSONObject task, long delayMillis) {
    cancelTaskTimer(taskId);
    scheduleTaskPrewarm(taskId, delayMillis);

    final long targetTime = task.optLong("planTime", 0);
    if (task.optBoolean("wakeOnTime", false)) {
        setAlarmForTask(taskId, targetTime);
    }

    Runnable runnable = new Runnable() {
        public void run() {
            long now = System.currentTimeMillis();
            if (now < targetTime) {
                scheduleHandler.postDelayed(this, Math.max(1, targetTime - now - 100));
                return;
            }
            if (System.currentTimeMillis() < targetTime) {
                scheduleHandler.postDelayed(this, Math.max(1, targetTime - System.currentTimeMillis()));
                return;
            }

            executeTaskSend(taskId);
        }
    };

    scheduledRunnables.put(taskId, runnable);
    scheduleHandler.postDelayed(runnable, Math.max(0, delayMillis));
}

/**
 * 精确执行单个任务
 */
void executeTaskSend(final String taskId) {
    final JSONObject task = (JSONObject) scheduledTasks.get(taskId);
    if (task == null) return;
    acquireMassSendWakeLock("定时任务:" + taskId);
    warmupSendPipeline(false, "before_executeTaskSend");

    long planTime = task.optLong("planTime", 0);
    long nowAtExecute = System.currentTimeMillis();
    if (planTime > 0 && nowAtExecute > planTime + 30000) {
        long lateMs = nowAtExecute - planTime;
        log("任务" + taskId + "晚点执行:" + lateMs + "ms，继续尝试发送");
    }

    final int type = task.optInt("type", 0);
    final String content = task.optString("content", "");
    final long interval = task.optLong("interval", 0);
    final long mediaInterval = task.optLong("mediaInterval", 0);

    JSONArray targetsJson = task.optJSONArray("targets");
    List<String> targets = new ArrayList<String>();
    if (targetsJson != null) {
        for (int i = 0; i < targetsJson.length(); i++) {
            targets.add(targetsJson.optString(i));
        }
    }

    JSONArray mediasJson = task.optJSONArray("medias");
    List<String> mediaPaths = new ArrayList<String>();
    if (mediasJson != null) {
        for (int i = 0; i < mediasJson.length(); i++) {
            mediaPaths.add(mediasJson.optString(i));
        }
    }

    try {
        task.put("status", "running");
    } catch (Exception e) {}
    saveAllTasks();

    notify("定时发送开始", "任务" + taskId.substring(0, 8) + "开始执行\n目标数:" + targets.size());

    final List<String> finalTargets = targets;
    final List<String> finalMediaPaths = mediaPaths;
    final JSONObject finalTask = task;

    exec(new Runnable() {
        public void run() {
            try {
            int success = 0;
            int fail = 0;

            // 朋友圈模式特殊处理
            if (type == SEND_TYPE_MOMENTS_TEXT || type == SEND_TYPE_MOMENTS_IMAGE) {
                try {
                    boolean ok = performSendWithRetry("朋友圈发送", true, new SendAction() {
                        public void run() throws Exception {
                            if (type == SEND_TYPE_MOMENTS_TEXT || finalMediaPaths.isEmpty()) {
                                uploadText(content);
                            } else {
                                uploadTextAndPicList(content, finalMediaPaths);
                            }
                        }
                    });
                    if (!ok) throw new RuntimeException("重试后仍失败");
                    success = 1;
                    notify("朋友圈发送成功", type == SEND_TYPE_MOMENTS_TEXT ? "已发送纯文本" : "已发送图文");
                } catch (Exception e) {
                    fail = 1;
                    log("朋友圈发送失败:" + e.getMessage());
                }
            } else {
                // 原有的群发逻辑
                for (int i = 0; i < finalTargets.size(); i++) {
                    final String target = finalTargets.get(i);
                    final String name = getContactName(target);
                    boolean targetSuccess = true;

                    try {
                        if (type == SEND_TYPE_TEXT) {
                            final String contentToSend = content.replace("%friendName%", name);
                            targetSuccess = performSendWithRetry("文本发送->" + target, false, new SendAction() {
                                public void run() throws Exception {
                                    sendText(target, contentToSend);
                                }
                            });
                        } else if (type == SEND_TYPE_XML) {
                            final String xmlToSend = content.replace("%friendName%", name);
                            targetSuccess = performSendWithRetry("XML发送->" + target, false, new SendAction() {
                                public void run() throws Exception {
                                    sendXmlMsg(target, xmlToSend);
                                }
                            });
                        } else {
                            for (int j = 0; j < finalMediaPaths.size(); j++) {
                                final String path = finalMediaPaths.get(j);
                                final File f = new File(path);
                                if (f.exists()) {
                                    boolean mediaOk = performSendWithRetry("媒体发送->" + target + "[" + f.getName() + "]", type == SEND_TYPE_VOICE, new SendAction() {
                                        public void run() throws Exception {
                                            switch (type) {
                                                case SEND_TYPE_IMAGE:
                                                    sendImage(target, path);
                                                    break;
                                                case SEND_TYPE_VIDEO:
                                                    sendVideo(target, path);
                                                    break;
                                                case SEND_TYPE_EMOJI:
                                                    sendEmoji(target, path);
                                                    break;
                                                case SEND_TYPE_FILE:
                                                    shareFile(target, f.getName(), path, "");
                                                    break;
                                                case SEND_TYPE_VOICE:
                                                    sendVoice(target, path);
                                                    break;
                                            }
                                        }
                                    });
                                    if (!mediaOk) {
                                        targetSuccess = false;
                                        break;
                                    }
                                    if (j < finalMediaPaths.size() - 1) {
                                        long mInterval = mediaInterval > 0 ? mediaInterval * 1000 : 500;
                                        Thread.sleep(mInterval);
                                    }
                                }
                            }
                        }
                    } catch (Exception e) {
                        targetSuccess = false;
                        log("发送失败:" + target + "-" + e.getMessage());
                    }

                    if (targetSuccess) success++; else fail++;

                    if (i < finalTargets.size() - 1 && interval > 0) {
                        try { Thread.sleep(interval * 1000); } catch (Exception e) {}
                    }
                }
            }

            final int fSuccess = success;
            final int fFail = fail;
            int repeatType = finalTask.optInt("repeatType", 0);
            JSONArray repeatDaysArray = finalTask.optJSONArray("repeatDays");

            try {
                if (repeatType > 0) {
                    long oldPlanTime = finalTask.optLong("planTime", 0);
                    final long newPlanTime = calculateNextPlanTime(oldPlanTime, repeatType, repeatDaysArray);

                    finalTask.put("planTime", newPlanTime);
                    finalTask.put("status", "pending");
                    finalTask.put("lastSuccessCount", fSuccess);
                    finalTask.put("lastFailCount", fFail);
                    finalTask.put("lastExecutedTime", System.currentTimeMillis());
                    saveAllTasks();

                    long delay = newPlanTime - System.currentTimeMillis();
                    scheduleTaskWithPrecision(taskId, finalTask, delay);

                    notify("重复任务完成一轮", "任务" + taskId.substring(0, 8) + "已安排下一次: \n" + formatTimeWithSeconds(newPlanTime));

                    new Handler(Looper.getMainLooper()).post(new Runnable() {
                        public void run() {
                            toast("本轮任务执行完毕，已排期下一次\n时间:" + formatTimeWithSeconds(newPlanTime));
                        }
                    });
                } else {
                    finalTask.put("status", "completed");
                    finalTask.put("successCount", fSuccess);
                    finalTask.put("failCount", fFail);
                    finalTask.put("completedTime", System.currentTimeMillis());
                    saveAllTasks();

                    cancelTaskTimer(taskId);
                    scheduledTasks.remove(taskId);
                    saveAllTasks();

                    final String report = "成功:" + fSuccess + ", 失败:" + fFail;
                    notify("定时发送完成", "任务" + taskId.substring(0, 8) + "已完成\n" + report);

                    new Handler(Looper.getMainLooper()).post(new Runnable() {
                        public void run() {
                            toast("任务执行完毕\n" + report);
                        }
                    });
                }
            } catch (Exception e) {
                log("任务完成收尾失败:" + e.getMessage());
            }
            } catch (Exception e) {
                log("任务执行异常:" + e.getMessage());
            } finally {
                releaseMassSendWakeLock("定时任务:" + taskId);
            }
        }
    });
}

/**
 * 计算重复任务的下一次执行时间
 */
long calculateNextPlanTime(long currentPlanTime, int repeatType, JSONArray repeatDaysArray) {
    Calendar cal = Calendar.getInstance();
    cal.setTimeInMillis(currentPlanTime);
    long now = System.currentTimeMillis();

    if (repeatType == 1) {
        do {
            cal.add(Calendar.DAY_OF_MONTH, 1);
        } while (cal.getTimeInMillis() <= now);
    } else if (repeatType == 2) {
        List<Integer> days = new ArrayList<Integer>();
        if (repeatDaysArray != null) {
            for (int i = 0; i < repeatDaysArray.length(); i++) {
                days.add(new Integer(repeatDaysArray.optInt(i)));
            }
        }
        if (days.isEmpty()) {
            cal.add(Calendar.DAY_OF_MONTH, 1);
            return cal.getTimeInMillis();
        }

        int safety = 365;
        do {
            cal.add(Calendar.DAY_OF_MONTH, 1);
            safety--;
        } while (safety > 0 && (!days.contains(new Integer(cal.get(Calendar.DAY_OF_WEEK))) || cal.getTimeInMillis() <= now));
    }

    return cal.getTimeInMillis();
}

/**
 * 格式化周天显示
 */
String formatRepeatDays(JSONArray arr) {
    if (arr == null || arr.length() == 0) return "未设置";
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < arr.length(); i++) {
        int d = arr.optInt(i);
        switch (d) {
            case Calendar.MONDAY: sb.append("一,"); break;
            case Calendar.TUESDAY: sb.append("二,"); break;
            case Calendar.WEDNESDAY: sb.append("三,"); break;
            case Calendar.THURSDAY: sb.append("四,"); break;
            case Calendar.FRIDAY: sb.append("五,"); break;
            case Calendar.SATURDAY: sb.append("六,"); break;
            case Calendar.SUNDAY: sb.append("日,"); break;
        }
    }
    if (sb.length() > 0) sb.setLength(sb.length() - 1);
    return sb.toString();
}

/**
 * 取消单个任务的定时器
 */
void cancelTaskTimer(String taskId) {
    Runnable runnable = (Runnable) scheduledRunnables.get(taskId);
    if (runnable != null) {
        scheduleHandler.removeCallbacks(runnable);
        scheduledRunnables.remove(taskId);
    }
    Runnable prewarmRunnable = (Runnable) taskPrewarmRunnables.get(taskId);
    if (prewarmRunnable != null) {
        scheduleHandler.removeCallbacks(prewarmRunnable);
        taskPrewarmRunnables.remove(taskId);
    }
    cancelAlarmForTask(taskId);
}

/**
 * 为任务设置系统级闹钟（尽量在后台也能按时唤醒微信）
 */
void setAlarmForTask(String taskId, long triggerTime) {
    try {
        Context ctx = getBestContext();
        if (ctx == null || triggerTime <= 0) return;

        android.content.Intent it = buildWeChatLaunchIntent(ctx);
        if (it == null) return;

        android.app.PendingIntent pi = buildTaskAlarmPendingIntent(ctx, taskId, it);
        android.app.AlarmManager am = (android.app.AlarmManager) ctx.getSystemService(Context.ALARM_SERVICE);
        if (am == null || pi == null) return;

        long alarmAt = Math.max(System.currentTimeMillis(), triggerTime - WAKEUP_LEAD_MS);

        try { am.cancel(pi); } catch (Exception ignored) {}

        try {
            if (Build.VERSION.SDK_INT >= 23) {
                am.setExactAndAllowWhileIdle(android.app.AlarmManager.RTC_WAKEUP, alarmAt, pi);
            } else if (Build.VERSION.SDK_INT >= 19) {
                am.setExact(android.app.AlarmManager.RTC_WAKEUP, alarmAt, pi);
            } else {
                am.set(android.app.AlarmManager.RTC_WAKEUP, alarmAt, pi);
            }
        } catch (SecurityException se) {
            // Android 12+ 可能因精确闹钟权限限制抛错，退化为非精确闹钟。
            if (Build.VERSION.SDK_INT >= 23) {
                am.setAndAllowWhileIdle(android.app.AlarmManager.RTC_WAKEUP, alarmAt, pi);
            } else {
                am.set(android.app.AlarmManager.RTC_WAKEUP, alarmAt, pi);
            }
        }
    } catch (Exception e) {
        log("设置系统闹钟失败:" + e.getMessage());
    }
}

/**
 * 取消任务对应的系统级闹钟
 */
void cancelAlarmForTask(String taskId) {
    try {
        Context ctx = getBestContext();
        if (ctx == null) return;

        android.content.Intent it = buildWeChatLaunchIntent(ctx);
        if (it == null) return;

        android.app.PendingIntent pi = buildTaskAlarmPendingIntent(ctx, taskId, it);
        android.app.AlarmManager am = (android.app.AlarmManager) ctx.getSystemService(Context.ALARM_SERVICE);
        if (am != null && pi != null) am.cancel(pi);
    } catch (Exception ignored) {}
}

Context getBestContext() {
    try {
        Context c = getTopActivity();
        if (c != null) return c;
    } catch (Exception ignored) {}
    try {
        Class at = Class.forName("android.app.ActivityThread");
        java.lang.reflect.Method m = at.getMethod("currentApplication", new Class[0]);
        Object app = m.invoke(null, new Object[0]);
        if (app instanceof Context) return (Context) app;
    } catch (Exception ignored) {}
    return null;
}

android.content.Intent buildWeChatLaunchIntent(Context ctx) {
    try {
        android.content.Intent it = ctx.getPackageManager().getLaunchIntentForPackage("com.tencent.mm");
        if (it == null) {
            it = new android.content.Intent();
            it.setClassName("com.tencent.mm", "com.tencent.mm.ui.LauncherUI");
            it.setAction(android.content.Intent.ACTION_MAIN);
            it.addCategory(android.content.Intent.CATEGORY_LAUNCHER);
        }
        it.addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK
                | android.content.Intent.FLAG_ACTIVITY_SINGLE_TOP
                | android.content.Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED);
        return it;
    } catch (Exception e) {
        log("构建微信启动Intent失败:" + e.getMessage());
        return null;
    }
}

android.app.PendingIntent buildTaskAlarmPendingIntent(Context ctx, String taskId, android.content.Intent launchIntent) {
    int flags = (Build.VERSION.SDK_INT >= 23)
            ? (android.app.PendingIntent.FLAG_UPDATE_CURRENT | android.app.PendingIntent.FLAG_IMMUTABLE)
            : android.app.PendingIntent.FLAG_UPDATE_CURRENT;
    return android.app.PendingIntent.getActivity(ctx, taskId.hashCode(), launchIntent, flags);
}

/**
 * 保存所有任务到存储
 */
void saveAllTasks() {
    try {
        JSONObject root = new JSONObject();
        Iterator it = scheduledTasks.keySet().iterator();
        while (it.hasNext()) {
            String taskId = (String) it.next();
            JSONObject task = (JSONObject) scheduledTasks.get(taskId);
            root.put(taskId, task);
        }
        putString(CONFIG_KEY, KEY_TASKS, root.toString());
    } catch (Exception e) {
        log("保存任务失败:" + e.getMessage());
    }
}

boolean loadDefaultSendOnTimeout() {
    String value = getString(CONFIG_KEY, KEY_DEFAULT_SEND_ON_TIMEOUT, "1");
    return "1".equals(value) || "true".equalsIgnoreCase(value);
}

void saveDefaultSendOnTimeout(boolean enabled) {
    putString(CONFIG_KEY, KEY_DEFAULT_SEND_ON_TIMEOUT, enabled ? "1" : "0");
}

boolean addCurrentTalkerToMassSendQueue(boolean showToast) {
    try {
        String talker = getTargetTalker();
        if (TextUtils.isEmpty(talker)) {
            if (showToast) toast("未获取到当前聊天 wxid");
            return false;
        }
        if (talker.endsWith("@chatroom") || talker.startsWith("wxid_") || talker.indexOf("@") < 0) {
            boolean added = massSendTargetWxids.add(talker);
            if (showToast) {
                toast((added ? "已添加到发送队列:" : "发送队列已存在:") + getContactName(talker));
            }
            return added;
        }
        if (showToast) toast("当前会话不支持加入发送队列:" + talker);
    } catch (Exception e) {
        if (showToast) toast("添加当前聊天失败:" + e.getMessage());
        try { log("添加当前聊天到群发队列失败:" + e.getMessage()); } catch (Exception ignore) {}
    }
    return false;
}


