void showLoadingDialog(String title, String message, final Runnable dataLoadTask) {
    LinearLayout initialLayout = new LinearLayout(getTopActivity());
    initialLayout.setOrientation(LinearLayout.HORIZONTAL);
    initialLayout.setPadding(50, 50, 50, 50);
    initialLayout.setGravity(Gravity.CENTER_VERTICAL);
    ProgressBar progressBar = new ProgressBar(getTopActivity());
    initialLayout.addView(progressBar);
    TextView loadingText = new TextView(getTopActivity());
    loadingText.setText(message);
    loadingText.setPadding(20, 0, 0, 0);  // ← 修复这里
    initialLayout.addView(loadingText);
    final AlertDialog loadingDialog = buildCommonAlertDialog(getTopActivity(), title, initialLayout, null, null, "取消", new DialogInterface.OnClickListener() {
        public void onClick(DialogInterface d, int w) { d.dismiss(); }
    }, null, null);
    loadingDialog.setCancelable(false);
    loadingDialog.show();
    exec(new Runnable() {
        public void run() {
            try {
                dataLoadTask.run();
            } finally {
                new Handler(Looper.getMainLooper()).post(new Runnable() {
                    public void run() {
                        try { loadingDialog.dismiss(); } catch (Exception e) {}
                    }
                });
            }
        }
    });
}

void setupListViewTouchForScroll(ListView listView) {
    listView.setOnTouchListener(new View.OnTouchListener() {
        public boolean onTouch(View v, MotionEvent event) {
            switch (event.getAction()) {
                case MotionEvent.ACTION_DOWN:
                    v.getParent().requestDisallowInterceptTouchEvent(true);
                    break;
                case MotionEvent.ACTION_UP:
                case MotionEvent.ACTION_CANCEL:
                    v.getParent().requestDisallowInterceptTouchEvent(false);
                    break;
    }
    return false;
}
    });
}

// ========== 黄狗音乐 (酷我) ==========

void searchKuwo(final Context c, final String keyword, final int page, final android.widget.LinearLayout results, final android.widget.TextView tvStatus, final android.widget.Button btnSearch,
                final android.widget.LinearLayout downloadBarLg, final android.widget.TextView tvDownloadNameLg, final android.widget.ProgressBar pbDownloadGlobalLg,
                final String[][] cachedLines, final int[] cachedPage, final String[] cachedKeyword,
                final android.widget.Button btnPrev, final android.widget.Button btnNext, final android.widget.TextView tvPage) {
    java.net.HttpURLConnection conn = null;
    try {
        int pn = (page - 1) * 20;
        String api = "https://search.kuwo.cn/r.s?all=" + java.net.URLEncoder.encode(keyword, "UTF-8")
            + "&ft=music&pn=" + pn + "&rn=20&rformat=json&encoding=utf8";
        log("kwyy: search api=" + api);
        conn = (java.net.HttpURLConnection) new java.net.URL(api).openConnection();
        conn.setConnectTimeout(10000); conn.setReadTimeout(10000);
        conn.setRequestProperty("User-Agent", "Mozilla/5.0 (iPhone; CPU iPhone OS 13_2_3 like Mac OS X)");
        conn.setRequestProperty("Referer", "https://www.kuwo.cn/");
        java.io.BufferedReader br = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), "UTF-8"));
        StringBuilder sb = new StringBuilder(); String line;
        while ((line = br.readLine()) != null) sb.append(line);
        br.close(); conn.disconnect(); conn = null;
        String raw = sb.toString();
        log("kwyy: raw len=" + raw.length());
        raw = raw.replace('\'', '"').replace("True", "true").replace("False", "false");
        org.json.JSONObject json = new org.json.JSONObject(raw);
        int total = Integer.parseInt(json.optString("TOTAL", "0"));
        org.json.JSONArray abslist = json.optJSONArray("abslist");
        if (abslist == null || abslist.length() == 0) {
            mainHandler.post(new Runnable() { public void run() { tvStatus.setText("未找到歌曲"); btnSearch.setEnabled(true); btnPrev.setVisibility(android.view.View.GONE); btnNext.setVisibility(android.view.View.GONE); } });
            return;
        }
        final int count = abslist.length();
        final int finalTotal = total;
        java.util.ArrayList<String> lines = new java.util.ArrayList<String>();
        for (int i = 0; i < count; i++) {
            org.json.JSONObject item = abslist.optJSONObject(i);
            if (item == null) continue;
            String musicrid = item.optString("MUSICRID", "");
            String name = item.optString("NAME", item.optString("SONGNAME", ""));
            String artist = item.optString("ARTIST", "");
            String album = item.optString("ALBUM", "");
            try {
                name = android.text.Html.fromHtml(name).toString().trim();
                artist = android.text.Html.fromHtml(artist).toString().trim();
                album = android.text.Html.fromHtml(album).toString().trim();
            } catch (Exception e) { log("kwyy: html decode err=" + e.getMessage()); }
            name = name.replace("|", " ").replace("\"", "'");
            artist = artist.replace("|", " ").replace("\"", "'");
            album = album.replace("|", " ").replace("\"", "'");
            String picpath = item.optString("web_albumpic_short", item.optString("web_artistpic_short", item.optString("MVPIC", item.optString("PICPATH", item.optString("img", item.optString("PIC", ""))))));
            if (!picpath.isEmpty()) picpath = picpath.replace("{size}", "240");
            if (picpath.isEmpty()) {
                String aid = item.optString("ALBUMID", "");
                if (!aid.isEmpty() && !aid.equals("0")) {
                    picpath = "https://img4.kuwo.cn/star/albumcover/240/" + aid + ".jpg";
                }
            }
            if (!picpath.isEmpty() && !picpath.startsWith("http")) picpath = "https://img4.kuwo.cn/star/albumcover/" + picpath;
            if (i < 3) {
                StringBuilder flds = new StringBuilder();
                java.util.Iterator keys = item.keys();
                while (keys.hasNext()) {
                    Object k = keys.next();
                    flds.append(k).append(",");
                }
                log("kwyy: fields[" + i + "]=" + flds.toString());
                log("kwyy: raw[" + i + "] PIC=" + item.optString("PIC","?") + " img=" + item.optString("img","?") + " PICPATH=" + item.optString("PICPATH","?") + " ALBUMID=" + item.optString("ALBUMID","?") + " ALBUM=" + item.optString("ALBUM","?"));
            }
            log("kwyy: cover[" + i + "]=" + picpath + " name=" + name + " aid=" + item.optString("ALBUMID",""));
            if (!name.isEmpty() && !musicrid.isEmpty()) {
                lines.add(musicrid + "|" + name + "|" + artist + "|" + album + "|" + picpath);
            }
        }
        final String[] allLines = lines.toArray(new String[0]);
        cachedLines[0] = allLines;
        cachedPage[0] = page;
        cachedKeyword[0] = keyword;
        mainHandler.post(new Runnable() {
            public void run() {
                int maxPage = (int) Math.ceil(finalTotal / 20.0);
                String pageStr = page + "/" + Math.max(maxPage, 1);
                tvStatus.setText(pageStr + " (共" + finalTotal + "首)");
                if (tvPage != null) tvPage.setText(pageStr + " 页");
                btnSearch.setEnabled(true);
                if (page > 1) { btnPrev.setVisibility(android.view.View.VISIBLE); btnPrev.setEnabled(true); } else { btnPrev.setVisibility(android.view.View.GONE); }
                if (page < maxPage) { btnNext.setVisibility(android.view.View.VISIBLE); btnNext.setEnabled(true); } else { btnNext.setVisibility(android.view.View.GONE); }
                results.removeAllViews();
                for (int i = 0; i < allLines.length; i++) {
                    String[] parts = allLines[i].split("\\|", 5);
                    if (parts.length >= 5) {
                        String musicrid = parts[0]; String name = parts[1]; String artist2 = parts[2];
                        String album2 = parts[3]; String picpath2 = parts[4];
                        addLgItem(c, i + 1, name, artist2, "", musicrid, picpath2,
                            results, downloadBarLg, tvDownloadNameLg, pbDownloadGlobalLg, null, null, "kuwo");
                    }
                }
            }
        });
    } catch (Exception e) {
        final String errMsg = e.getMessage();
        log("kwyy: search error: " + (errMsg != null ? errMsg : "nil"));
        if (conn != null) { try { conn.disconnect(); } catch (Exception ignored) {} }
        mainHandler.post(new Runnable() { public void run() { tvStatus.setText("搜索失败: " + (errMsg != null ? errMsg : "网络错误")); btnSearch.setEnabled(true); } });
    }
}

