void parseVideoDownload(String url, String title) {
    toast("开始下载...");
    exec(new Runnable() {
        public void run() {
            String path = parseVideoDownloadFile(url, title);
            final String fpath = path;
            mainHandler.post(new Runnable() {
                public void run() { toast(fpath != null ? "下载完成" : "下载失败"); }
            });
        }
    });
}

String parseVideoDownloadFile(String url, String title) {
    java.net.HttpURLConnection conn = null;
    java.io.InputStream is = null;
    java.io.FileOutputStream fos = null;
    try {
        java.net.URL u = new java.net.URL(url);
        conn = (java.net.HttpURLConnection) u.openConnection();
        conn.setInstanceFollowRedirects(true);
        conn.setRequestMethod("GET");
        conn.setConnectTimeout(15000);
        conn.setReadTimeout(60000);
        conn.setRequestProperty("User-Agent", "Mozilla/5.0");
        conn.connect();
        is = conn.getInputStream();
        java.io.File dir = new java.io.File("/storage/emulated/0/Download/乐少助手");
        if (!dir.exists()) dir.mkdirs();
        String safeName = title;
        if (safeName == null || safeName.isEmpty()) safeName = String.valueOf(System.currentTimeMillis());
        safeName = safeName.replaceAll("[\\\\/:*?\"<>|]", "_");
        if (safeName.length() > 40) safeName = safeName.substring(0, 40);
        java.io.File outFile = new java.io.File(dir, "parse_" + safeName + "_" + System.currentTimeMillis() + ".mp4");
        fos = new java.io.FileOutputStream(outFile);
        byte[] buf = new byte[8192];
        int len;
        while ((len = is.read(buf)) != -1) fos.write(buf, 0, len);
        fos.flush();
        log("videoParse: download done path=" + outFile.getAbsolutePath());
        return outFile.getAbsolutePath();
    } catch (Exception e) {
        log("videoParse: download error: " + e.getMessage());
        return null;
    } finally {
        try { if (fos != null) fos.close(); } catch (Exception ignored) {}
        try { if (is != null) is.close(); } catch (Exception ignored) {}
        if (conn != null) { try { conn.disconnect(); } catch (Exception ignored) {} }
    }
}

void autoPlayVoiceMsg(long voiceDuration) {
    String amrPath = pollForVoiceFile(0);
    if (amrPath == null) {
        log("autoPlayVoice: no AMR file found");
        return;
    }
    synchronized (processedAmrList) {
        if (processedAmrList.contains(amrPath)) {
            log("autoPlayVoice: already processed " + amrPath);
            return;
        }
        if (processedAmrList.size() > 50) processedAmrList.remove(0);
        processedAmrList.add(amrPath);
    }

    while (true) {
        synchronized (messageQueue) {
            if (!isSpeaking) {
                isSpeaking = true;
                break;
            }
        }
        try { Thread.sleep(150); } catch (Exception e) {}
    }

    try {
        playAmrWithMediaPlayer(amrPath);
    } finally {
        mainHandler.post(new Runnable() {
            public void run() { processNextQueued(); }
        });
    }
}

String pollForVoiceFile(int retryCount) {
    if (retryCount > 6) return null;
    if (retryCount > 0) {
        try { Thread.sleep(500); } catch (Exception e) {}
    }
    String path = getRealLatestVoiceFile();
    if (path != null) return path;
    return pollForVoiceFile(retryCount + 1);
}

String getRealLatestVoiceFile() {
    try {
        java.io.File microMsgDir = new java.io.File("/data/user/0/com.tencent.mm/MicroMsg/");
        if (!microMsgDir.exists()) return null;

        java.io.File targetVoiceDir = null;
        long lastModified = 0;

        java.io.File[] userDirs = microMsgDir.listFiles();
        if (userDirs != null) {
            for (java.io.File dir : userDirs) {
                if (dir.isDirectory() && dir.getName().length() == 32) {
                    java.io.File v2 = new java.io.File(dir, "voice2");
                    if (v2.exists() && v2.lastModified() > lastModified) {
                        lastModified = v2.lastModified();
                        targetVoiceDir = v2;
                    }
                }
            }
        }

        if (targetVoiceDir == null) return null;

        java.io.File newestL2 = null;
        long maxL2Time = 0;

        java.io.File[] l1Arr = targetVoiceDir.listFiles();
        if (l1Arr != null) {
            for (java.io.File l1 : l1Arr) {
                if (l1.isDirectory()) {
                    java.io.File[] l2Arr = l1.listFiles();
                    if (l2Arr != null) {
                        for (java.io.File l2 : l2Arr) {
                            if (l2.isDirectory() && l2.lastModified() > maxL2Time) {
                                maxL2Time = l2.lastModified();
                                newestL2 = l2;
                            }
                        }
                    }
                }
            }
        }

        if (newestL2 != null) {
            return getNewestAmrInDir(newestL2);
        }
    } catch (Exception e) {
        log("getRealLatestVoiceFile: " + e.getMessage());
    }
    return null;
}

String getNewestAmrInDir(java.io.File dir) {
    java.io.File[] files = dir.listFiles();
    if (files == null) return null;
    java.io.File newest = null;
    long maxTime = 0;
    for (java.io.File f : files) {
        if (f.isFile() && f.getName().endsWith(".amr") && f.length() > 0 && f.lastModified() > maxTime) {
            maxTime = f.lastModified();
            newest = f;
        }
    }
    return newest != null ? newest.getAbsolutePath() : null;
}

void probeIljAllMethods() {
    try {
        Class engineClass = hostContext.getClassLoader().loadClass("il.j");
        java.lang.reflect.Method[] methods = engineClass.getDeclaredMethods();
        log("probeIljAll: total declared = " + methods.length);
        for (int i = 0; i < methods.length; i++) {
            String mName = methods[i].getName();
            Class[] params = methods[i].getParameterTypes();
            StringBuilder sb = new StringBuilder("probeIljAll: ").append(mName).append("(");
            for (int j = 0; j < params.length; j++) {
                if (j > 0) sb.append(", ");
                sb.append(params[j].getSimpleName());
            }
            sb.append(") -> ").append(methods[i].getReturnType().getSimpleName());
            log(sb.toString());
        }
    } catch (Exception e) {
        log("probeIljAll: " + e.getMessage());
    }

    try {
        java.util.List classKeys = new java.util.ArrayList();
        classKeys.add("playVoice");
        classKeys.add("voice2");
        java.util.List foundClasses = findClassList(classKeys);
        log("DexKit playVoice+voice2: found " + (foundClasses != null ? foundClasses.size() : 0) + " classes");
        if (foundClasses != null) {
            for (int i = 0; i < foundClasses.size() && i < 20; i++) {
                log("DexKit class: " + foundClasses.get(i).toString());
            }
        }
    } catch (Exception e) {
        log("DexKit playVoice: " + e.getMessage());
    }

    try {
        java.util.List amrKeys = new java.util.ArrayList();
        amrKeys.add(".amr");
        amrKeys.add("startPlay");
        java.util.List amrClasses = findClassList(amrKeys);
        log("DexKit amr+startPlay: found " + (amrClasses != null ? amrClasses.size() : 0) + " classes");
        if (amrClasses != null) {
            for (int i = 0; i < amrClasses.size() && i < 20; i++) {
                log("DexKit amr: " + amrClasses.get(i).toString());
            }
        }
    } catch (Exception e) {
        log("DexKit amr: " + e.getMessage());
    }
}

boolean playAmrWithMediaPlayer(String amrPath) {
    try {
        String mp3Path = amrPath.replace(".amr", ".mp3");
        silkToMp3(amrPath, mp3Path);
        java.io.File mp3File = new java.io.File(mp3Path);
        for (int i = 0; i < 30; i++) {
            try { Thread.sleep(100); } catch (Exception e) {}
            if (mp3File.exists() && mp3File.length() > 0) break;
        }
        if (mp3File.exists() && mp3File.length() > 0) {
            android.media.MediaPlayer mp = new android.media.MediaPlayer();
            mp.setDataSource(mp3Path);
            mp.setAudioStreamType(android.media.AudioManager.STREAM_MUSIC);
            mp.prepare();
            mp.start();
            int waitCount = 0;
            while (mp.isPlaying() && waitCount < 150) {
                try { Thread.sleep(200); } catch (Exception e) {}
                waitCount++;
            }
            mp.release();
            try { mp3File.delete(); } catch (Exception e) {}
            return true;
        }
    } catch (Exception e) {
        log("autoPlayVoice: " + e.getMessage());
    }
    return false;
}
